NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Acts'

CHAPTERS = {
    1: {
        1: '§ Prejšnje poročilo sem naredil, oh Teófil, o vsem, kar je Jezus začel, tako delati kakor učiti,',
        2: 'do dne, v katerem je bil vzet gor, potem ko je po Svetem Duhu dal zapovedi apostolom, ki jih je izbral;',
        3: '§ katerim se je, po svojem trpljenju, tudi pokazal živega, z mnogimi nezmotljivimi dokazi, ki so jih gledali štirideset dni in govorili o stvareh, ki se nanašajo na Božje kraljestvo;',
        4: 'in ko je bil zbran skupaj z njimi, jim je zapovedal, da naj ne odidejo iz Jeruzalema, temveč čakajo na Očetovo obljubo: »Katero,« on pravi, »ste slišali od mene.',
        5: 'Kajti Janez je resnično krščeval z vodo, toda vi boste krščeni s Svetim Duhom, čez ne mnogo dni.«',
        6: 'Ko so torej prišli skupaj, so ga vprašali, rekoč: »Gospod, ali boš v tem času Izraelu ponovno obnovil kraljestvo?«',
        7: 'In rekel jim je: »Ni za vas, da bi vedeli čase ali obdobja, ki jih je Oče postavil v svoji lastni oblasti.',
        8: 'Toda prejeli boste moč, po tem, ko Sveti Duh pride nad vas, in vi mi boste priče, tako v Jeruzalemu kakor po vsej Judeji in v Samariji ter do skrajnega dela zemlje.«',
        9: 'In ko je govoril te besede, medtem ko so ga gledali, je bil vzet gor, in oblak ga je sprejel iz njihovega pogleda.',
        10: 'In medtem ko so neomajno gledali proti nebu, ko je šel gor, glej, sta poleg njih stala dva moža v belih oblekah,',
        11: 'ki sta prav tako rekla: »Vi, možje iz Galileje, zakaj stojite strmeč v nebo? Ta isti Jezus, ki je bil od vas vzet gor v nebesa, bo prišel tako, na podoben način, kakor ste ga videli iti v nebo.«',
        12: 'Tedaj so se z gore, imenovane Oljska, ki je šabatni dan poti od Jeruzalema, vrnili v Jeruzalem.',
        13: 'In ko so prišli vanj, so odšli gor v gornjo sobo, kjer so prebivali Peter in Jakob in Janez in Andrej, Filip in Tomaž, Bartolomej in Matej, Alfejev sin Jakob in Simon Gorečnik ter Jakobov brat Juda.',
        14: 'Vsi ti so soglasno vztrajali v molitvi in ponižni prošnji z ženskami in Marijo, Jezusovo materjo ter z njegovimi brati.',
        15: 'In v tistih dneh je sredi učencev vstal Peter ter rekel (skupno število imen je bilo okoli sto dvajset):',
        16: '»Možje in bratje, to pismo se je brezpogojno moralo izpolniti, ki ga je Sveti Duh po Davidovih ustih prej govoril glede Juda, ki je bil vodnik tem, ki so prijeli Jezusa.',
        17: 'Kajti bil je štet z nami in je dosegel delež te službe.',
        18: 'Torej ta človek je s krivično nagrado kupil polje in ko je padel z glavo naprej, se je po sredi razpočil in vsa njegova notranjost se je izlila ven.',
        19: 'In to je bilo znano vsem jeruzalemskim prebivalcem, tako zelo, da se to polje v njihovem pravem jeziku imenuje Hakéldama, to se pravi: ›Njiva krvi.‹',
        20: 'Kajti pisano je v knjigi Psalmov: ›Naj bo njegovo prebivališče zapuščeno in naj noben človek ne prebiva v njem in njegovo duhovno nadzorništvo naj prevzame nekdo drug.‹',
        21: 'Zatorej izmed teh ljudi, ki so se z nami družili ves čas, ko je Gospod Jezus hodil med nami noter in ven,',
        22: 'začenši od Janezovega krsta do tega istega dne, ko je bil od nas vzet gor, mora biti nekdo odrejen, da bo z nami priča njegovega vstajenja.«',
        23: 'In določili so dva, Jožefa, imenovanega Bársaba, ki je bil imenovan z vzdevkom Just ter Matija.',
        24: 'In molili so ter rekli: »Ti, Gospod, ki poznaš srca vseh ljudi, pokaži, katerega izmed teh dveh si izbral,',
        25: '§ da lahko prevzame del te službe in apostolstva, od katerega je Juda s prestopkom odpadel, da bi lahko šel na svoj lasten kraj.«',
        26: 'In naznanili so svoje žrebe in žreb je padel na Matija in ta je bil prištet enajsterim apostolom.',
    },
    2: {
        1: 'In ko je popolnoma prišel Binkoštni dan, so bili vsi soglasni na enem kraju.',
        2: 'In nenadoma je prišel z neba šum kakor besneč mogočen veter ter napolnil vso hišo, kjer so sedeli.',
        3: 'In prikazali so se jim razcepljeni jeziki, podobni ognjenim ter sedli na vsakogar izmed njih.',
        4: 'In vsi so bili izpolnjeni s Svetim Duhom in začeli so govoriti z drugimi jeziki, kakor jim je Duh dajal izgovarjati.',
        5: 'V Jeruzalemu pa so prebivali Judje, predani možje, iz vsakega naroda pod nebom.',
        6: 'Torej, ko se je to razglasilo naokoli, so prišle skupaj množice in bili so zbegani, zato ker jih je vsakdo slišal govoriti v svojem lastnem jeziku.',
        7: 'In vsi so bili osupli ter se čudili in drug drugemu govorili: »Glejte, ali niso vsi ti, ki govorijo, Galilejci?',
        8: 'In kako mi vsakega človeka slišimo v svojem lastnem jeziku, kjer smo bili rojeni?',
        9: 'Parti in Medijci in Elámci in prebivalci v Mezopotamiji in v Judeji in Kapadokiji, v Pontu in Aziji,',
        10: 'Frigiji in Pamfiliji, v Egiptu in v libijskih krajih okoli Cirene in tujci iz Rima, Judje in spreobrnjenci,',
        11: 'Krečani in Arabci, mi jih v svojih jezikih slišimo govoriti čudovita Božja dela.«',
        12: 'In vsi so bili osupli in bili so v dvomu, govoreč drug drugemu: »Kaj to pomeni?«',
        13: 'Drugi so zasmehljivo rekli: »Ti ljudje so polni novega vina.«',
        14: 'Vendar je Peter, ko je javno nastopil z enajsterimi, povzdignil svoj glas in jim rekel: »Vi ljudje iz Judeje in vsi vi, ki prebivate v Jeruzalemu, to vam bodi znano in prisluhnite mojim besedam,',
        15: 'kajti ti niso pijani, kakor vi mislite, glede na to, da je šele tretja dnevna ura.',
        16: 'Ampak to je to, kar je bilo rečeno po preroku Joélu:',
        17: '›In zgodilo se bo v poslednjih dneh, govori Bog: ›Izlil bom od svojega Duha na vse meso, in vaši sinovi in vaše hčere bodo prerokovali in vaši mladeniči bodo videli videnja in vaši starci bodo sanjali sanje;',
        18: 'in na svoje služabnike in na svoje pomočnice bom v tistih dneh izlil od svojega Duha in bodo prerokovali;',
        19: 'in pokazal bom čudeže zgoraj na nebu in znamenja spodaj na zemlji: kri in ogenj in dimne meglice;',
        20: 'sonce se bo spremenilo v temo in luna v kri, preden pride ta veliki in opazni dan Gospodovega prihoda.',
        21: 'In zgodilo se bo, da kdorkoli se bo skliceval na Gospodovo ime, bo rešen.‹‹',
        22: 'Vi, možje Izraelci, prisluhnite tem besedam. Jezus Nazarečan, mož med vami, po čudežnih močeh, čudežih in znamenjih potrjen od Boga, ki jih je Bog po njem storil v sredi med vami, kakor tudi vi sami veste;',
        23: 'njega, ki je bil izročen po določeni nameri in vnaprejšnjem védenju Boga, ste vi prijeli in po zlobnih rokah križali ter umorili,',
        24: '§ ki ga je Bog dvignil in odvezal bolečin smrti; ker ni bilo mogoče, da bi ga ta zadržala.',
        25: 'Kajti David glede njega govori: ›Vedno sem slutil Gospoda pred svojim obrazom, kajti on je na moji desnici, da ne bi bil omajan.',
        26: 'Zato se je moje srce veselilo in moj jezik je bil vesel; poleg tega bo tudi moje meso počivalo v upanju,',
        27: '§ ker moje duše nočeš pustiti v peklu niti nočeš trpeti, da bi tvoj Sveti videl trohnenje.',
        28: 'Spoznati si mi dal poti življenja; s svojim obličjem me boš napravil polnega radosti.‹',
        29: 'Možje in bratje, naj vam odkrito spregovorim o očaku Davidu, da je tako mrtev kakor pokopan in njegov mavzolej je med nami do današnjega dne.',
        30: '§ Ker je bil torej prerok in je vedel, da mu je Bog prisegel s prisego, da bo od sadu njegovih ledij, glede na meso, vzdignil Kristusa, da sedi na njegovem prestolu;',
        31: '§ in ker je to videl vnaprej, je govoril o Kristusovem vstajenju, da njegova duša ni ostala v peklu niti njegovo meso ni videlo trohnenja.',
        32: 'Tega Jezusa je Bog vzdignil, o čemer smo mi vsi priče.',
        33: 'Torej je bil z Božjo desnico povišan in je od Očeta prejel obljubo Svetega Duha, ki ga je razlil, kakor sedaj vidite in slišite.',
        34: 'Kajti David ni dvignjen v nebesa, toda on sam pravi: › Gospod je rekel mojemu Gospodu: ›Sedi na mojo desnico,',
        35: 'dokler ne naredim tvojih sovražnikov [za] tvojo pručko.‹‹',
        36: 'Zato naj vsa Izraelova hiša brez dvoma ve, da je Bog tega istega Jezusa, ki ste ga vi križali, naredil tako Gospoda kakor Kristusa.«',
        37: 'Torej ko so to slišali, so bili v svojem srcu spodbujeni ter rekli Petru in ostalim apostolom: »Možje in bratje, kaj naj storimo?«',
        38: 'Potem jim je Peter rekel: »Pokesajte se in vsak izmed vas naj bo krščen v imenu Jezusa Kristusa v odpuščanje grehov in prejeli boste dar Svetega Duha.',
        39: 'Kajti obljuba je dana vam in vašim otrokom in vsem, ki so daleč stran, celó tolikim, kolikor jih bo poklical Gospod, naš Bog.«',
        40: 'In z mnogimi drugimi besedami je pričeval ter spodbujal, rekoč: »Rešite se iz tega sprijenega rodu.«',
        41: 'Potem so bili tisti, ki so z veseljem sprejeli njegovo besedo, krščeni in istega dne se jim je dodalo okoli tri tisoč duš.',
        42: 'In neomajno so nadaljevali v apostolskem nauku in družbi in v lomljenju kruha ter v molitvah.',
        43: 'In strah je prišel nad vsako dušo; in po apostolih je bilo storjenih mnogo čudežev in znamenj.',
        44: 'In vsi, ki so verovali, so bili skupaj in vse stvari so imeli skupne;',
        45: 'in prodajali so svoje posesti ter dobrine in jih delili vsem ljudem, kolikor je vsak potreboval.',
        46: 'In vsak dan so soglasno nadaljevali v templju in od hiše do hiše lomili kruh [in] z veseljem in iskrenim srcem jedli svojo hrano,',
        47: 'ter slavili Boga in imeli naklonjenost pri vseh ljudeh. Gospod pa je k cerkvi dnevno dodajal takšne, ki naj bi bili rešeni.',
    },
    3: {
        1: 'Torej Peter in Janez sta ob uri molitve skupaj odšla gor v tempelj; bila je deveta ura.',
        2: 'Nekega moža, hromega od maternice njegove matere, pa so nosili in ga dnevno polagali pri tempeljskih velikih vratih, ki se imenujejo Lepa, da prosi miloščine od teh, ki so vstopali v tempelj,',
        3: 'ki je, ko je videl Petra in Janeza namenjena v tempelj, prosil miloščine.',
        4: 'In ko se je Peter z Janezom zazrl v njegove oči, je rekel: »Poglej naju.«',
        5: 'In ta jima je posvetil pozornost, ker je pričakoval, da bo od njiju kaj prejel.',
        6: 'Potem je Peter rekel: »Srebra in zlata nimam, toda to, kar imam, ti dam: ›V imenu Jezusa Kristusa iz Nazareta vstani in hôdi.‹«',
        7: 'In prijel ga je za desnico ter ga dvignil in takoj so njegova stopala ter kosti gležnja prejeli moč.',
        8: 'In poskočil je pokonci ter hodil in z njima vstopil v tempelj, kjer je hodil in poskakoval ter slavil Boga.',
        9: 'In vsi ljudje so ga videli hoditi in slaviti Boga',
        10: 'in vedeli so, da je bil to ta, ki je zaradi miloščine sedel pri tempeljskih Lepih velikih vratih. In izpolnjeni so bili s čudenjem ter osuplostjo nad tem, kar se mu je zgodilo.',
        11: 'In medtem ko se je hromi mož, ki je bil ozdravljen, držal Petra in Janeza, so vsi ljudje, ker so se silno čudili, skupaj stekli k njima v preddverje, ki se je imenovalo Salomonovo.',
        12: 'In ko je Peter to videl, je ljudem odgovoril: »Vi, možje iz Izraela, zakaj se čudite nad tem? Ali zakaj tako iskreno gledate na naju, kakor da bi z najino lastno močjo ali svetostjo tega moža pripravila hoditi?',
        13: '§ Bog Abrahama in Izaka in Jakoba, Bog naših očetov, je proslavil svojega Sina Jezusa, ki ste ga vi izročili in ga zatajili v Pilatovi prisotnosti, ko je bil ta odločen, da ga izpusti.',
        14: 'Toda zatajili ste Svetega in Pravičnega ter prosili, da se vam zagotovi morilec;',
        15: '§ ubili pa ste Princa življenja, ki ga je Bog obudil od mrtvih; o čemer smo mi priče.',
        16: 'In njegovo ime je po veri v njegovo ime tega moža naredilo močnega, ki ga vidite in poznate. Da, vera, ki je po njem, mu je dala to popolno zdravje v prisotnosti vas vseh.',
        17: 'In sedaj, bratje, vem, da ste to storili po nevednosti, kakor so storili tudi vaši vladarji.',
        18: '§ Toda te besede, ki jih je Bog prej oznanil po ustih vseh svojih prerokov, da naj bi Kristus trpel, je on tako izpolnil.',
        19: '§ Pokesajte se torej in bodite spreobrnjeni, da bodo vaši grehi lahko izbrisani, ko bodo od Gospodove prisotnosti prišli časi osvežitve;',
        20: '§ in poslal bo Jezusa Kristusa, ki vam je bil prej oznanjen,',
        21: 'ki ga morajo sprejeti nebesa do časov obnovitve vseh stvari, ki jih je Bog govoril po ustih vseh svojih svetih prerokov, odkar je svet nastal.',
        22: 'Kajti Mojzes je očetom resnično rekel: ›Preroka vam bo Gospod, vaš Bog, vzdignil izmed vaših bratov, podobnega meni; njega boste poslušali v vseh stvareh, karkoli vam bo govoril.',
        23: 'In zgodilo se bo, da bo vsaka duša, ki ne bo poslušala tega preroka, uničena izmed ljudi.‹',
        24: 'Da, in vsi preroki od Samuela in tisti, ki so sledili, kolikor jih je govorilo, so enako napovedali o teh dneh.',
        25: 'Vi ste otroci prerokov in zaveze, ki jo je Bog sklenil z našimi očeti, rekoč Abrahamu: ›In v tvojem semenu bodo blagoslovljena vsa sorodstva zemlje.‹',
        26: '§ K vam je najprej Bog, ki je vzdignil svojega Sina Jezusa, njega poslal, da vas blagoslovi z odvračanjem vsakega izmed vas od njegovih krivičnosti.«',
    },
    4: {
        1: 'In medtem ko sta govorila ljudem, so nadnju prišli duhovniki in tempeljski stotnik ter saduceji,',
        2: 'ki so bili užaloščeni, da sta učila ljudi in oznanjala vstajenje od mrtvih po Jezusu.',
        3: '§ In nanju so položili roke ter ju zadržali do naslednjega dne, kajti sedaj je bil večer.',
        4: 'Vendar so mnogi izmed teh, ki so slišali besedo, verovali; in število ljudi je bilo okoli pet tisoč.',
        5: 'In pripetilo se je naslednji dan, da so se njihovi vladarji in starešine in pisarji',
        6: 'in Hana, véliki duhovnik in Kajfa in Janez in Aleksander in kolikor jih je bilo iz sorodstva vélikega duhovnika, skupaj zbrali v Jeruzalemu.',
        7: 'In ko so ju postavili medse, so vprašali: »S kakšno močjo ali s čigavim imenom sta to naredila?«',
        8: 'Tedaj jim je Peter, izpolnjen s Svetim Duhom, rekel: »Vi vladarji ljudi in starešine v Izraelu,',
        9: 'če sva ta dan zasliševana o dobrem delu, storjenem nemočnemu človeku, na kakšen način je bil on ozdravljen;',
        10: 'bodi znano vam vsem in vsem ljudem v Izraelu, da v imenu Jezusa Kristusa iz Nazareta, ki ste ga križali, ki ga je Bog obudil od mrtvih, celó po njem ta človek sedaj tukaj pred vami stoji ozdravljen.',
        11: '§ To je kamen, ki je bil zaničevan od vas graditeljev, ki je postal glava vogalu.',
        12: 'Niti ni rešitve duš v nikomer drugem, kajti pod nebom med ljudmi ni dano drugega imena, s katerim moremo biti rešeni.«',
        13: 'Torej ko so videli Petrov in Janezov pogum ter zaznali, da sta bila neizobražena in nepoučena človeka, so se čudili; in o njiju so spoznali, da sta bila z Jezusom.',
        14: 'In ko so gledali moža, ki je bil ozdravljen, stati z njimi, proti temu niso mogli reči ničesar.',
        15: 'Toda ko so jima zapovedali, da se odstranita od vélikega zbora, so se med seboj posvetovali,',
        16: 'rekoč: »Kaj naj storimo tema možema? Kajti ta zares opazen čudež, storjen po njima, je očiten vsem tistim, ki prebivajo v Jeruzalemu; in tega ne moremo zanikati.',
        17: 'Toda da se to ne razširi naprej med ljudmi, jima strogo zagrozimo, da odslej nobenemu človeku ne govorita v tem imenu.«',
        18: 'In poklicali so ju ter jima zapovedali sploh ne govoriti niti učiti v Jezusovem imenu.',
        19: 'Toda Peter in Janez sta odgovorila in jim rekla: »Sami presodite, ali je v Božjih očeh bolj pravilno poslušati vas kakor Boga.',
        20: 'Kajti midva ne moreva, da ne bi govorila stvari, ki sva jih videla in slišala.«',
        21: 'Torej ko so jima še naprej grozili, so ju izpustili zaradi ljudi, ker niso našli ničesar, da bi ju lahko kaznovali, kajti vsi ljudje so slavili Boga za to, kar je bilo storjeno.',
        22: 'Kajti mož, na katerem se je prikazal ta čudež ozdravljenja, je bil star več kot štirideset let.',
        23: 'In ko sta bila izpuščena, sta odšla k svoji lastni druščini ter poročala o vsem, kar so jima visoki duhovniki in starešine rekli.',
        24: 'In ko so oni to slišali, so svoje glasove soglasno povzdignili k Bogu ter rekli: »Gospod, ti si Bog, ki je naredil nebo in zemljo in morje ter vse, kar je v njih,',
        25: 'ki si po ustih svojega služabnika Davida rekel: ›Zakaj besnijo pogani in si ljudje domišljajo prazne stvari?',
        26: 'Kralji zemlje so vstali in vladarji so bili skupaj zbrani zoper Gospoda in zoper njegovega Kristusa.‹',
        27: '§ Kajti resnično so se proti tvojemu svetemu otroku Jezusu, ki si ga ti mazilil, skupaj zbrali tako Herod kakor Poncij Pilat s pogani in Izraelovi ljudje,',
        28: 'da storijo, karkoli je tvoja roka in tvoja namera poprej določila, da se stori.',
        29: 'In sedaj, Gospod, glej njihove grožnje in zagotovi svojim služabnikom, da bodo lahko z vsem pogumom govorili tvojo besedo,',
        30: 'z iztegnitvijo svoje roke, da ozdravlja; in da bodo znamenja in čudeži lahko storjeni z imenom tvojega svetega otroka Jezusa.«',
        31: 'In ko so molili, se je zatresel kraj, kjer so bili skupaj zbrani; in vsi so bili izpolnjeni s Svetim Duhom in s pogumom so govorili Božjo besedo.',
        32: 'Množica teh, ki so verovali, pa je bila enega srca in ene duše; niti nobeden izmed njih ni rekel, da je bilo karkoli od stvari, ki jih je imel v lasti, njegovo, temveč so vse stvari imeli skupne.',
        33: 'Apostoli pa so z veliko močjo podajali pričevanje o vstajenju Gospoda Jezusa, in nad njimi vsemi je bila velika milost.',
        34: 'Niti ni bilo med njimi nikogar, ki bi trpel pomanjkanje, kajti kolikor jih je bilo lastnikov zemljišč ali hiš, so jih prodali in prinesli vrednost stvari, ki so bile prodane',
        35: 'in jih polagali k stopalom apostolov in narejena je bila porazdelitev vsakemu človeku glede na njegovo potrebo.',
        36: 'In Jožef, ki je bil po apostolih imenovan z vzdevkom Barnaba (kar je prevedeno: ›Sin tolažbe‹), Lévijevec in iz dežele Cipra,',
        37: 'je imel zemljo, jo prodal in prinesel denar ter ga položil k stopalom apostolov.',
    },
    5: {
        1: 'Toda nek človek, po imenu Hananija, je s Safíro, svojo ženo, prodal posestvo',
        2: 'in zadržal del denarne vsote in tudi njegova žena je bila seznanjena s tem in prinesel je določen del ter ga položil k stopalom apostolov.',
        3: 'Toda Peter je rekel: »Hananija, zakaj je Satan napolnil tvoje srce, da lažeš Svetemu Duhu in da zadržiš del vsote od zemljišča?',
        4: 'Dokler je ostajalo ali ni bilo tvoje lastno? In potem, ko je bilo prodano ali ni bilo v tvoji lastni oblasti? Zakaj si v svojem srcu spočel to stvar? Nisi lagal ljudem, temveč Bogu.«',
        5: 'In ko je Hananija slišal te besede, je padel dol ter izročil duha. In velik strah je prišel na vse tiste, ki so slišali te stvari.',
        6: 'Mladeniči pa so vstali, ga ovili in ga odnesli ven ter ga pokopali.',
        7: 'In bilo je približno tri ure kasneje, ko je vstopila njegova žena, ki ni vedela, kaj se je bilo zgodilo.',
        8: 'In Peter jo je ogovoril: »Povej mi ali sta za toliko prodala zemljišče?« In ona je rekla: »Da, za toliko.«',
        9: 'Tedaj ji je Peter rekel: »Kako je to, da sta se skupaj strinjala, da skušata Gospodovega Duha? Glej, stopala teh, ki so pokopala tvojega soproga, so pri vratih in odnesli te bodo ven.«',
        10: 'Potem je nemudoma padla ob njegovih stopalih in izročila duha. In vstopili so mladeniči ter jo našli mrtvo in ko so jo odnesli, so jo pokopali poleg njenega soproga.',
        11: 'In velik strah je prišel nad vso cerkev in nad vse, ki so slišali te stvari.',
        12: 'Po rokah apostolov pa se je med ljudmi zgodilo mnogo znamenj in čudežev; (in vsi so bili s soglasjem v Salomonovem preddverju.',
        13: 'Od preostalih pa se jim noben človek ni drznil pridružiti, toda ljudje so jih poveličevali.',
        14: 'In še več vernikov je bilo dodanih h Gospodu, množice tako moških kakor žensk.)',
        15: 'Toliko, da so na ulice prinašali bolne in jih polagali na postelje ter ležišča, da bi lahko vsaj Petrova senca, ko je šel mimo, zasenčila nekatere izmed njih.',
        16: 'Tudi ven iz mest naokoli Jeruzalema je prišla množica, ki je prinašala bolne ljudi in te, ki so bili nadlegovani z nečistimi duhovi; in vsi so bili ozdravljeni.',
        17: 'Tedaj je vstal véliki duhovnik in vsi tisti, ki so bili z njim (kar je saducejska ločina) in izpolnjeni so bili z ogorčenjem',
        18: 'in svoje roke so položili na apostole ter jih vtaknili v skupno ječo.',
        19: 'Toda Gospodov angel je ponoči odprl vrata ječe in jih privedel naprej ter rekel:',
        20: '»Pojdite, stopíte in govorite ljudem v templju vse besede tega življenja.«',
        21: 'In ko so to slišali, so zgodaj zjutraj vstopili v tempelj ter učili. Toda prišel je véliki duhovnik in tisti, ki so bili z njim in so sklicali skupaj véliki zbor in ves senat Izraelovih otrok in poslali k ječi, da bi jih privedli.',
        22: 'Toda ko so prišli častniki in jih niso našli v ječi, so se vrnili ter povedali,',
        23: 'rekoč: »Ječo smo resnično našli zaprto z vso varnostjo in čuvaje, ki so stali zunaj pred vrati, toda ko smo odprli, v njej nismo našli nobenega človeka.«',
        24: 'Torej ko so véliki duhovnik in tempeljski stotnik ter visoki duhovniki slišali te besede, so se bali k čému se bo to razvilo.',
        25: 'Tedaj je nekdo prišel ter jim povedal, rekoč: »Glejte, možje, ki ste jih vtaknili v ječo, stojijo v templju in učijo ljudi.«',
        26: 'Tedaj je stotnik s častniki odšel in jih privedel brez nasilja, kajti bali so se ljudi, da jih ne bi kamnali.',
        27: 'In ko so jih privedli, so jih postavili pred véliki zbor in véliki duhovnik jih je vprašal,',
        28: 'rekoč: »Ali vam nismo strogo zapovedali, da naj ne bi učili v tem imenu? In glejte, Jeruzalem ste napolnili s svojim naukom in nad nas nameravate privesti kri tega človeka.«',
        29: 'Potem so Peter in drugi apostoli odgovorili ter rekli: »Mi moramo bolj ubogati Boga kakor ljudi.',
        30: 'Bog naših očetov je obudil Jezusa, ki ste ga vi usmrtili in obesili na les.',
        31: '§ Njega je Bog s svojo desnico povišal, da postane Princ in Odrešenik, da bi Izraelu dal kesanje in odpuščanje grehov.',
        32: 'In mi smo njegove priče o teh stvareh; in tako je tudi Sveti Duh, ki ga je Bog dal tistim, ki ga ubogajo.«',
        33: 'Ko so to slišali, so bili do srca zbodeni in se posvetovali, da jih ubijejo.',
        34: 'Potem je nekdo v vélikem zboru vstal, farizej, po imenu Gamáliel, učen mož postave, ugleden med vsemi ljudmi in velel, da jih za nekaj časa vržejo ven;',
        35: 'in jim rekel: »Vi, možje v Izraelu, pazite se, kaj nameravate storiti glede teh ljudi.',
        36: 'Kajti pred temi dnevi je vstal Tevdá, ki se je bahal, da je pomemben; kateremu so se pridružili številni ljudje, okoli štiristo; ki je bil umorjen, in vsi, kolikor se mu jih je pokoravalo, so bili razkropljeni in uničeni.',
        37: 'Po tem možu je, v dneh obdavčenja, vstal Juda iz Galileje in za seboj potegnil mnogo ljudi; tudi on je umrl in vsi so bili razkropljeni, celó tako mnogi, kot so ga ubogali.',
        38: 'In sedaj vam povem: ›Zadržite se pred temi ljudmi in pustite jih pri miru. Kajti če je ta namera ali to delo od ljudi, se bo izjalovilo;',
        39: 'toda če je to od Boga, tega ne morete premagati, da ne bi bili morda najdeni celo, da se borite zoper Boga.‹«',
        40: 'In strinjali so se z njim. Ko pa so poklicali apostole ter jih pretepli, so jim zapovedali, da naj ne govorijo v Jezusovem imenu in jih izpustili.',
        41: 'In odšli so izpred prisotnosti vélikega zbora, veseli, da so bili spoznani za vredne trpeti sramoto zaradi njegovega imena.',
        42: 'In niso prenehali v templju in v vsaki hiši vsak dan učiti ter oznanjati Jezusa Kristusa.',
    },
    6: {
        1: 'In v tistih dneh, ko je bilo število učencev pomnoženo, je nastalo mrmranje Grkov zoper Hebrejce, ker so bile njihove vdove zapostavljene pri vsakodnevni oskrbi.',
        2: 'Potem je dvanajsterica k sebi poklicala množico učencev in rekla: »To ni razlog, da bi opuščali Božjo besedo in stregli [pri] mizah.',
        3: 'Zatorej bratje, poiščite med seboj sedem mož, na dobrem glasu, polnih Svetega Duha in modrosti, ki jim lahko določimo to opravilo.',
        4: 'Toda mi se bomo predali v nenehno molitev in službo besede.«',
        5: 'In ta beseda je ugajala vsej množici. In izbrali so Štefana, moža, polnega vere in Svetega Duha in Filipa in Prohorja in Nikánorja in Timona in Parmenája ter Nikolaja, spreobrnjenca iz Antiohije,',
        6: 'ki jih so postavili pred apostole. In ko so molili, so nanje položili svoje roke.',
        7: 'In Božja beseda je rasla in število učencev v Jeruzalemu se je silno pomnožilo in velika skupina duhovnikov je bila pokorna veri.',
        8: 'In Štefan je, poln vere in moči, delal med ljudmi velike čudeže in čudežne moči.',
        9: 'Potem so vstali nekateri iz sinagoge, ki se je imenovala sinagoga Libertincev in Cirencev in Aleksandríncev in teh iz Kilikije ter iz Azije in so razpravljali s Štefanom.',
        10: 'Niso pa se mogli upirati modrosti in duhu, po katerem je govoril.',
        11: 'Tedaj so podkupili može, ki so rekli: »Slišali smo ga govoriti bogokletne besede zoper Mojzesa in zoper Boga.«',
        12: 'In razvneli so ljudi in starešine ter pisarje in prišli nad njega in ga zgrabili ter ga privedli k vélikemu zboru',
        13: 'in postavili krive priče, ki so rekle: »Ta človek ne preneha govoriti bogokletnih besed proti temu svetemu prostoru in postavi,',
        14: 'kajti slišali smo ga govoriti, da bo ta Jezus Nazarečan uničil ta kraj in spremenil običaje, ki nam jih je izročil Mojzes.«',
        15: 'In vsi, ki so sedeli v vélikem zboru, so neomajno zrli vanj in videli njegov obraz, kot bi bil obraz angela.',
    },
    7: {
        1: 'Potem je véliki duhovnik rekel: »Ali so te stvari take?«',
        2: 'In rekel je: »Možje, bratje in očetje, prisluhnite: ›Bog slave se je prikazal našemu očetu Abrahamu, ko je bil v Mezopotamiji, preden je prebival v Haránu',
        3: 'in mu rekel: ›Pojdi ven iz svoje dežele in iz svojega sorodstva ter pridi v deželo, ki ti jo bom pokazal.‹‹',
        4: '§ Tedaj je prišel iz kaldejske dežele in prebival v Haránu; ko pa je bil njegov oče mrtev, se je od tam odpravil v to deželo, v kateri vi sedaj prebivate.',
        5: 'V njej pa mu ni dal nobene dediščine niti toliko ne, da nanjo postavi svoje stopalo, vendar je obljubil, da mu jo bo dal v posest in njegovemu semenu za njim, ko takrat še ni imel otroka.',
        6: 'In Bog je govoril na ta način: ›Da naj bi njegovo seme začasno bivalo v tuji deželi in da naj bi jih privedli v suženjstvo ter štiristo let z njimi hudobno ravnali.',
        7: 'Narodu pa, pri katerem bodo suženjevali, bom sodil jaz,‹ je rekel Bog: ›in potem bodo prišli ter mi služili na tem kraju.‹',
        8: 'In dal mu je zavezo obrezovanja. In tako je Abraham zaplodil Izaka in ga osmi dan obrezal; in Izak je zaplodil Jakoba; in Jakob je zaplodil dvanajstere očake.',
        9: 'In očaki so, prevzeti z zavistjo, Jožefa prodali v Egipt. Toda Bog je bil z njim',
        10: 'in ga osvobodil iz vseh njegovih stisk in mu dal naklonjenost ter modrost v očeh faraona, egiptovskega kralja in ga naredil za voditelja nad Egiptom ter vso svojo hišo.',
        11: 'Torej nad vso egiptovsko deželo in Kánaan je prišlo pomanjkanje in velika stiska in naši očetje niso našli hrane.',
        12: 'Toda ko je Jakob slišal, da je bilo v Egiptu žito, je najprej odposlal naše očete.',
        13: 'In ob drugi priložnosti se je Jožef dal spoznati svojim bratom; in Jožefovo sorodstvo je bilo predstavljeno faraonu.',
        14: 'Potem je Jožef odposlal in k sebi poklical svojega očeta Jakoba in vse njegovo sorodstvo, petinsedemdeset duš.',
        15: 'Tako je Jakob odšel dol v Egipt ter umrl, on in naši očetje',
        16: 'in bili so preneseni preko v Sihem in položeni v mavzolej, ki ga je Abraham kupil za vsoto denarja od sinov Hemórja, očeta iz Sihema.',
        17: 'Toda ko se je približal obljubljeni čas, ki ga je Bog prisegel Abrahamu, so ljudje v Egiptu rasli in se množili,',
        18: 'dokler ni vstal drug kralj, ki ni poznal Jožefa.',
        19: 'Ta isti je z našim sorodstvom premeteno ravnal in hudobno tretiral naše očete, tako da so izpostavili svoje majhne otroke, z namenom, da ne bi živeli.',
        20: 'V tem času je bil rojen Mojzes, bil pa je silno lep in tri mesece so ga vzgajali v hiši njegovega očeta.',
        21: 'Ko pa je bil izpostavljen, ga je vzela faraonova hči in ga vzgojila za svojega lastnega sina.',
        22: 'In Mojzes je bil izučen v vsej egipčanski modrosti in mogočen je bil v besedah in dejanjih.',
        23: 'Ko je bil star polnih štirideset let, je prišlo v njegovo srce, da obišče svoje brate, Izraelove otroke.',
        24: 'In ko je videl enega izmed njih krivično trpeti, ga je branil in maščeval tega, ki je bil zatiran ter ubil Egipčana,',
        25: 'kajti domneval je, da bodo njegovi bratje razumeli, kako jih hoče Bog po njegovi roki osvoboditi. Toda niso razumeli.',
        26: 'In medtem ko so se prepirali, se jim je naslednji dan pokazal ter jih ponovno skušal pomiriti, rekoč: ›Možje, vi ste bratje; zakaj drug drugemu delate krivico?‹',
        27: 'Toda tisti, ki je svojemu bližnjemu storil krivico, ga je odrinil proč, rekoč: ›Kdo te je naredil za vladarja in sodnika nad nami?',
        28: 'Ali me hočeš ubiti, kakor si včeraj storil Egipčanu?‹',
        29: 'Ob tej besedi je Mojzes pobegnil in bil tujec v midjánski deželi, kjer je zaplodil dva sinova.',
        30: 'Ko pa je preteklo štirideset let, se mu je v divjini Sinajske gore prikazal Gospodov angel v plamenu gorečega grma.',
        31: 'Ko je Mojzes to videl, se je čudil prizoru. Ko pa se je približal, da bi to pogledal, je prišel do njega Gospodov glas,',
        32: 'rekoč: ›Jaz sem Bog tvojih očetov, Bog Abrahamov in Bog Izakov in Bog Jakobov.‹ Potem je Mojzes trepetal in si ni drznil pogledati.',
        33: 'Nato mu je Gospod rekel: ›Sezuj si svoje čevlje s svojih stopal, kajti kraj, kjer stojiš, je sveta zemlja.',
        34: 'Videl sem, videl sem stisko svojih ljudi, ki so v Egiptu in slišal sem njihovo stokanje in sem prišel dol, da jih osvobodim. In sedaj pridi, poslal te bom v Egipt.‹',
        35: 'Tega Mojzesa, ki so ga zavrnili, rekoč: ›Kdo te je naredil vladarja in sodnika?‹ istega je Bog poslal, da bi bil vladar in osvoboditelj po roki angela, ki se mu je prikazal v grmu.',
        36: 'Potem ko je v egiptovski deželi in v Rdečem morju ter v divjini štirideset let prikazoval čudeže in znamenja, jih je privedel ven.',
        37: '§ To je ta Mojzes, ki je Izraelovim otrokom rekel: ›Preroka vam bo Gospod, vaš Bog, obudil izmed vaših bratov, podobnega meni; njega boste poslušali.‹',
        38: '§ To je tisti, ki je bil v cerkvi v divjini z angelom, ki je govoril z njim na Sinajski gori in z našimi očeti; ki je prejel žive prerokbe, da jih izroči nam;',
        39: 'katerega naši očetje niso hoteli ubogati, temveč so ga pahnili od sebe in se v svojih srcih ponovno obrnili nazaj v Egipt,',
        40: 'rekoč Aronu: ›Naredi nam bogove, da gredo pred nami, kajti glede tega Mojzesa, ki nas je privedel iz egiptovske dežele, ne vemo, kaj je nastalo iz njega.‹',
        41: 'In v tistih dneh so naredili tele in maliku darovali žrtev ter se veselili v delih svojih lastnih rok.',
        42: 'Potem se je Bog obrnil in jih predal, da obožujejo vojsko neba; kakor je pisano v knjigi prerokov: ›Oh hiša Izraelova ali ste meni darovali zaklane živali in žrtve v obdobju štiridesetih let v divjini?',
        43: 'Da, vzeli ste Molohov šotor in zvezdo svojega boga Rajfána, kipe, ki ste jih naredili, da bi jih oboževali; jaz pa vas bom odvedel onstran Babilona.‹',
        44: 'Naši očetje so imeli v divjini šotorsko svetišče pričevanja, kakor je določil on, govoreč Mojzesu, da naj ga naredi glede na videz, ki ga je videl.',
        45: '§ Katerega so tudi naši očetje, ki so prišli kasneje, vnesli z Jezusom na posest poganov, ki jih je Bog pregnal izpred obličja naših očetov do Davidovih dni;',
        46: 'ki je našel naklonjenost pred Bogom in si želel najti šotorsko svetišče za Jakobovega Boga.',
        47: 'Toda Salomon mu je zgradil hišo.',
        48: 'Vendar Najvišji ne prebiva v templjih, zgrajenimi z rokami; kakor pravi prerok:',
        49: '›Nebesa so moj prestol in zemlja je moja pručka. Kakšno hišo mi hočete zgraditi?‹ govori Gospod: ›Ali kaj je prostor mojega počitka?',
        50: 'Ali ni vse te stvari naredila moja roka?‹',
        51: 'Vi trdovratni in neobrezani v srcu in ušesih, vi se vedno upirate Svetemu Duhu. Kakor so počeli vaši očetje, tako počnete vi.',
        52: 'Katerega izmed prerokov vaši očetje niso preganjali? In umorili so te, ki so vnaprej kazali na prihod Pravičnega, katerega izdajalci in morilci ste bili sedaj vi,',
        53: 'ki ste po uredbi angelov prejeli postavo, pa se je niste držali.«',
        54: 'Ko so slišali te besede, so bili zarezani do srca in s svojimi zobmi so škripali proti njemu.',
        55: 'Toda on je, poln Svetega Duha, neomajno gledal gor v nebesa in videl Božjo slavo ter Jezusa stati na Božji desnici.',
        56: 'In rekel: »Glejte, nebesa vidim odprta in Sina človekovega stati na Božji desnici.«',
        57: 'Tedaj so z močnim glasom zakričali in zamašili svoja ušesa ter soglasno stekli nadenj',
        58: 'in ga vrgli iz mesta ter ga kamnali. Priče pa so svoja oblačila položile k stopalom mladeniča, katerega ime je bilo Savel.',
        59: 'In kamnali so Štefana, ki je klical k Bogu ter govoril: »Gospod Jezus, sprejmi mojega duha.«',
        60: 'In pokleknil je ter z močnim glasom zaklical: »Gospod, tega greha jim ne položi na njihovo obtožnico.« In ko je to rekel, je zaspal.',
    },
    8: {
        1: 'In Savel je privolil v njegovo smrt. In ob tistem času je bilo tam veliko preganjanje zoper cerkev, ki je bila v Jeruzalemu; in vsi, razen apostolov, so bili razkropljeni povsod po vseh področjih Judeje in Samarije.',
        2: 'In predani možje so Štefana odnesli k njegovemu pokopu ter za njim pripravili veliko objokovanje.',
        3: 'Toda Savel je napravil veliko opustošenje cerkve, ko je vstopal v vsako hišo in vlačil [ven] moške in ženske ter jih zapiral v ječo.',
        4: 'Zaradi tega so tisti, ki so bili razkropljeni naokoli, odšli povsod in oznanjali besedo.',
        5: 'Potem je Filip odšel dol v samarijsko mesto in jim oznanil Kristusa.',
        6: 'In množica je soglasno dala pozornost tem stvarem, ki jih je Filip govoril in poslušala ter gledala čudeže, ki jih je delal.',
        7: 'Kajti nečisti duhovi so kričê, z močnim glasom prihajali iz mnogih, ki so bili z njimi obsedeni. In mnogi prevzeti s paralizo ter tisti, ki so bili hromi, so bili ozdravljeni.',
        8: 'In v tistem mestu je bila velika radost.',
        9: 'Vendar je bil tam nek mož, imenovan Simon, ki je poprej v istem mestu uporabljal čaranje in privlačil pogane iz Samarije ter objavljal, da je bil on sam nekaj velikega,',
        10: 'ki so mu vsi posvetili pozornost, od najmanjših do največjih, rekoč: »Ta mož je velika Božja moč.«',
        11: 'In ozirali so se nanj, zato ker jih je že dolgo časa privlačil s svojimi čarodejstvi.',
        12: 'Toda ko so verovali Filipu, ki je oznanjal besede glede Božjega kraljestva in ime Jezusa Kristusa, so bili krščeni, tako moški kakor ženske.',
        13: 'Potem je tudi sam Simon veroval; in ko je bil krščen, je ostal s Filipom in se čudil ter gledal čudeže in znamenja, ki so bila storjena.',
        14: 'Ko so torej apostoli, ki so bili v Jeruzalemu, slišali, da je Samarija sprejela Božjo besedo, so jim poslali Petra in Janeza,',
        15: 'ki sta, ko sta prišla dol, molila zanje, da bi mogli prejeti Svetega Duha',
        16: '(kajti do takrat še ni padel na nobenega izmed njih. Bili so samo krščeni v imenu Gospoda Jezusa.)',
        17: 'Tedaj sta nanje polagala svoje roke in prejemali so Svetega Duha.',
        18: 'In ko je Simon videl, da je bil Sveti Duh dan po polaganju rok apostolov, jima je ponudil denar,',
        19: 'rekoč: »Dajta tudi meni to moč, da na kogarkoli položim roke, bo lahko prejel Svetega Duha.«',
        20: 'Vendar mu je Peter rekel: »Tvoj denar naj propade s teboj, ker si pomislil, da se Božji dar lahko kupi z denarjem.',
        21: 'Ti nimaš niti vloge niti deleža v tej stvari, kajti tvoje srce ni iskreno v Božjih očeh.',
        22: 'Pokesaj se torej od te svoje zlobnosti in prosi Boga, če ti bo mogoče lahko odpuščena misel tvojega srca.',
        23: 'Kajti zaznavam, da si v žolču grenkobe in v vezi krivičnosti.«',
        24: 'Potem je Simon odgovoril in rekel: »Prosita zame h Gospodu, da nobena izmed teh stvari, ki sta jih govorila, ne pride nadme.«',
        25: 'In onadva, ko sta pričevala in oznanila Gospodovo besedo, sta se vrnila v Jeruzalem ter v mnogih vaseh Samarije oznanila evangelij.',
        26: 'Gospodov angel pa je spregovoril Filipu, rekoč: »Vstani in pojdi proti jugu, na pot, ki gre dol iz Jeruzalema v Gazo, ki je zapuščena.«',
        27: 'In vstal je ter odšel. In glej, človek iz Etiopije, evnuh z veliko oblastjo pod Kandáko, kraljico Etiopijcev, ki je imel skrb za vso njeno zakladnico in je prišel v Jeruzalem, da bi oboževal,',
        28: 'se je vračal in sedé na svoji kočiji bral preroka Izaija.',
        29: 'Potem je Duh rekel Filipu: »Pojdi poleg in se pridruži tej kočiji.«',
        30: 'In Filip je stekel tja k njemu in ga slišal brati preroka Izaija ter rekel: »Razumeš, kaj bereš?«',
        31: 'In rekel je: »Kako bi lahko, razen če me ne bi vodil nek človek?« In prosil je Filipa, da pride gor in se usede z njim.',
        32: 'Mesto iz pisma, ki ga je bral, je bilo to: ›Odveden je bil kakor ovca h klanju; in kakor je jagnje pred svojim strižcem nemo, tako on ni odprl svojih ust.',
        33: 'V njegovem ponižanju je bila njegova sodba odstranjena in kdo bo razglašal njegov rod? Kajti njegovo življenje je vzeto z zemlje.‹',
        34: 'In evnuh je odgovoril Filipu ter rekel: »Prosim te, o kom govori to prerok? O sebi ali nekem drugem človeku?«',
        35: 'Potem je Filip odprl svoja usta in začel pri istem pismu in mu oznanil Jezusa.',
        36: 'In medtem ko sta nadaljevala po njuni poti, sta prišla do neke vode, in evnuh je rekel: »Poglej, tukaj je voda, kaj mi preprečuje biti krščen?«',
        37: '§ In Filip je rekel: »Če veruješ z vsem svojim srcem, smeš.« In ta je odgovoril ter rekel: »Verujem, da je Jezus Kristus Božji Sin.«',
        38: 'In velel je kočiji, da se ustavi. In skupaj sta odšla dol v vodo, tako Filip kakor evnuh; in ga je krstil.',
        39: 'In ko sta se povzpela iz vode, je Gospodov Duh Filipa vzel, da ga evnuh ni več videl in ta je radosten odšel na svojo pot.',
        40: 'Toda Filip se je znašel pri Ašdódu. In ko je potoval skozi, je v vseh mestih oznanjal, dokler ni prišel do Cezareje.',
    },
    9: {
        1: 'Savel pa, ki je še vedno izdihoval grožnje in poboj zoper Gospodove učence, je odšel k vélikemu duhovniku',
        2: 'in si od njega izprosil pisem za shodnice v Damasku, da če najde kogarkoli od te poti, bodisi moške ali ženske, bi jih lahko zvezane privedel v Jeruzalem.',
        3: 'Medtem ko je potoval, se je približal Damasku in nenadoma je naokoli njega zasvetila svetloba iz nebes',
        4: 'in padel je na tla ter zaslišal glas, ki mu je rekel: »Savel, Savel, zakaj me preganjaš?«',
        5: '§ On pa je rekel: »Kdo si ti, Gospod?« In Gospod je rekel: »Jaz sem Jezus, ki ga ti preganjaš. Zate je to težko, da se upiraš bodicam.«',
        6: '§ In ta je trepetajoč in osupel rekel: »Gospod, kaj hočeš, da storim?« In Gospod mu je rekel: »Vstani in pojdi v mesto in povedano ti bo, kaj moraš storiti.«',
        7: 'Možje, ki so potovali z njim, pa so stali brez besed, ker so poslušali glas, vendar niso videli nobenega človeka.',
        8: 'In Savel se je dvignil s tal in ko so bile njegove oči odprte, ni videl nobenega človeka, ampak so ga vodili za roko in ga privedli v Damask.',
        9: 'In tri dni je bil brez vida in ni ne jedel, ne pil.',
        10: 'V Damasku pa je bil nek učenec, po imenu Hananija in njemu je Gospod v videnju rekel: »Hananija.« In ta je rekel: »Glej, jaz sem tu, Gospod.«',
        11: 'In Gospod mu je rekel: »Vstani in pojdi v ulico, ki se imenuje Ravna in v Judovi hiši povprašaj za nekoga, ki se imenuje Savel iz Tarza; kajti glej, on moli',
        12: 'in v videnju je videl moža, imenovanega Hananija, ki je vstopil in nanj položil svojo roko, da bi lahko prejel svoj vid.«',
        13: 'Potem je Hananija odgovoril: »Gospod, od mnogih sem slišal o tem človeku, koliko zla je storil tvojim svetim v Jeruzalemu',
        14: 'in tukaj ima od visokih duhovnikov oblast, da zveže vse, ki kličejo tvoje ime.«',
        15: 'Toda Gospod mu je rekel: »Odpravi se, kajti on mi je izbrana posoda, da ponese moje ime pred pogane in kralje in Izraelove otroke,',
        16: 'kajti pokazal mu bom, kako velike stvari mora trpeti zaradi mojega imena.«',
        17: 'In Hananija je odšel svojo pot ter vstopil v hišo in ko je svoje roke položil nanj, je rekel: »Brat Savel, Gospod, celó Jezus, ki se ti je prikazal na poti, ko si prihajal, me je poslal, da lahko prejmeš svoj vid in izpolnjen boš s Svetim Duhom.«',
        18: 'In takoj so z njegovih oči padle, kot bi bile luskine, in nemudoma je prejel vid in vstal ter bil krščen.',
        19: 'In ko je prejel hrano, je bil okrepljen. Potem je bil Savel nekaj dni z učenci, ki so bili v Damasku.',
        20: 'In nemudoma je v sinagogah oznanjal Kristusa, da je on Božji Sin.',
        21: 'Toda vsi, ki so ga slišali, so bili osupli in rekli: »Ali ni to tisti, ki je uničil tiste, ki so se v Jeruzalemu sklicevali na to ime in je prišel sèm zaradi tega namena, da bi jih lahko zvezane privedel k visokim duhovnikom?«',
        22: 'Toda Savel je še bolj narasel v moči in zbegal Jude, ki so prebivali v Damasku ter dokazoval, da je ta pravi Kristus.',
        23: 'In potem, ko so bili izpolnjeni mnogi dnevi, so se Judje posvetovali, da ga ubijejo,',
        24: 'toda njihovo prežanje v zasedi je bilo sporočeno Savlu. In noč in dan so stražili velika vrata, da ga ubijejo.',
        25: 'Potem so ga učenci ponoči vzeli in ga v košari spustili dol ob obzidju.',
        26: 'In ko je Savel prišel v Jeruzalem, se je poskusil pridružiti učencem, toda vsi so se ga bali in niso verjeli, da je bil učenec.',
        27: 'Vendar ga je Barnaba vzel in ga privedel k apostolom ter jim razodel, kako je na poti videl Gospoda in da mu je govoril ter kako je v Damasku pogumno oznanjal v Jezusovem imenu.',
        28: 'In bil je z njimi in prihajal in odhajal iz Jeruzalema.',
        29: 'In pogumno je govoril v imenu Gospoda Jezusa ter se prerekal proti Grkom, toda oni so ga poskušali umoriti.',
        30: 'Nakar, ko so bratje [to] izvedeli, so ga odvedli dol v Cezarejo in ga poslali v Tarz.',
        31: 'Potem so imele cerkve po vsej celotni Judeji in Galileji ter Samariji mir in se izgrajevale, in ker so živele v strahu Gospodovem ter v tolažbi Svetega Duha, so bile pomnožene.',
        32: 'In pripetilo se je, ko je Peter potoval po vseh celotnih okoliših, [da] je prišel tudi dol k svetim, ki so prebivali v Lidi.',
        33: 'In tam je našel nekega moža, po imenu Enéj, ki se je osem let držal svoje postelje in je bil bolan zaradi paralize.',
        34: 'In Peter mu je rekel: »Enéj, Jezus Kristus te celostno ozdravlja. Vstani in postelji svojo posteljo.« In ta je takoj vstal.',
        35: 'In vsi tisti, ki so prebivali v Lidi in Šarónu, so ga videli ter se obrnili h Gospodu.',
        36: 'Torej v Jopi je bila neka učenka, po imenu Tabíta, kar se po razlagi imenuje Gazela. Ta ženska je bila polna dobrih del in dejanj miloščine, ki jih je storila.',
        37: 'In pripetilo se je v tistih dneh, da je bila bolna in je umrla. Ko so jo umili, so jo položili v zgornjo sobo.',
        38: 'Ker pa je bila Lida blizu Jope in so učenci slišali, da je bil tam Peter, so k njemu poslali dva moža, ki sta ga prosila, da ne bi odlašal priti k njim.',
        39: 'Potem je Peter vstal in odšel z njima. Ko je prišel, so ga odvedli v zgornjo sobo, in vse vdove so jokaje stale poleg njega in kazale plašče ter obleke, ki jih je naredila Gazela, dokler je bila z njimi.',
        40: 'Vendar jih je Peter vse vrgel ven ter pokleknil in molil, in ko se je obrnil k telesu, je rekel: »Tabíta, vstani.« In odprla je svoje oči, in ko je zagledala Petra, se je usedla.',
        41: 'In dal ji je svojo roko ter jo dvignil. In ko je poklical svete ter vdove, jo je izročil živo.',
        42: 'In to se je razvedelo po vsej celotni Jopi in mnogi so verovali v Gospoda.',
        43: 'In pripetilo se je, da je mnogo dni ostal v Jopi pri nekem strojarju Simonu.',
    },
    10: {
        1: 'V Cezareji je bil nek mož, imenovan Kornelij, stotnik čete, imenovana itálska četa,',
        2: 'predan mož in nekdo, ki se je z vso svojo hišo bal Boga, ki je ljudem dajal veliko miloščine in vedno molil k Bogu.',
        3: 'Okoli devete dnevne ure je v videnju jasno videl Božjega angela prihajati k njemu, rekoč mu: »Kornelij.«',
        4: 'In ko je pogledal nanj, je bil prestrašen in rekel: »Kaj je, Gospod?« On pa mu je rekel: »Tvoje molitve in tvoje miloščine so prišle gor v spomin pred Boga.',
        5: 'In sedaj pošlji može v Jopo in pokliči nekega Simona, katerega vzdevek je Peter.',
        6: '§ Ta prenočuje pri nekem strojarju Simonu, čigar hiša je ob morski obali. On ti bo povedal, kaj moraš storiti.«',
        7: 'In ko je angel, ki je govoril Korneliju, odšel, je ta poklical dva izmed svojih hišnih služabnikov in predanega vojaka izmed teh, ki so nenehno čakali nanj',
        8: 'in ko jim je razglasil vse te stvari, jih je poslal v Jopo.',
        9: 'Naslednji dan, ko so odšli na svoje potovanje in se približali mestu, se je Peter okoli šeste ure povzpel na hišno streho, da bi molil.',
        10: 'Postal pa je zelo lačen in bi želel jesti, toda medtem ko so pripravljali, je padel v zamaknjenje',
        11: 'in videl odprto nebo ter nekakšno posodo spuščati se k njemu, kot bi bil to velik pleten prt s štirimi vogali in se spuščal k zemlji,',
        12: 'v katerem so bile vse vrste štirinožnih zemeljskih živali in divjih zveri in plazečih stvari ter perjad neba.',
        13: 'In do njega je prišel glas: »Vstani, Peter, zakolji in jej.«',
        14: 'Vendar je Peter rekel: »Ne tako, Gospod, kajti še nikoli nisem jedel česarkoli, kar je oskrunjeno ali nečisto.«',
        15: 'Glas pa mu je ponovno, drugič, rekel: »Kar je Bog očistil, tega ne imenuj oskrunjeno.«',
        16: 'To se je zgodilo trikrat in posoda je bila ponovno sprejeta gor v nebo.',
        17: 'Torej medtem ko je bil Peter v sebi zaskrbljen, kaj bi to videnje, ki ga je videl, lahko pomenilo, glej, so možje, ki so bili poslani od Kornelija, povprašali po Simonovi hiši in stali pred velikimi vrati',
        18: 'in zaklicali ter vprašali, ali je tam prenočeval Simon, ki je bil imenovan z vzdevkom Peter.',
        19: 'Medtem ko je Peter premišljeval o videnju, mu je Duh rekel: »Glej, trije možje te iščejo.',
        20: 'Vstani torej in se spusti ter pojdi z njimi in nič ne dvomi, kajti jaz sem jih poslal.«',
        21: '§ Potem je Peter odšel dol k možem, ki so bili k njemu poslani od Kornelija in rekel: »Glejte, jaz sem ta, ki ga iščete. Kakšen je razlog, zaradi česar ste prišli?«',
        22: 'In rekli so: »Stotnik Kornelij, pravičen mož in nekdo, ki se boji Boga ter je na dobrem glasu med vsem judovskim narodom, je bil po svetem angelu od Boga obveščen, da pošlje v to hišo pote in da od tebe sliši besede.«',
        23: 'Potem jih je poklical noter in jih prenočil. In naslednji dan je Peter z njimi odšel, spremljali pa so ga neki bratje iz Jope.',
        24: 'In naslednji dan so vstopili v Cezarejo. In Kornelij jih je pričakoval ter sklical skupaj svoje sorodnike in bližnje prijatelje.',
        25: 'In ko je Peter vstopil, ga je srečal Kornelij in padel dol k njegovim stopalom ter ga oboževal.',
        26: 'Vendar ga je Peter dvignil, rekoč: »Vstani, tudi jaz sem človek.«',
        27: 'In medtem ko se je pogovarjal z njim, je vstopil ter našel mnoge, ki so bili zbrani skupaj.',
        28: 'In rekel jim je: »Vi veste, da je to nezakonita stvar za človeka, ki je Jud, da se druži ali pride k nekomu iz drugega naroda. Toda Bog mi je pokazal, da naj nobenega človeka ne imenujem oskrunjenega ali nečistega.',
        29: 'Zato sem brez ugovarjanja prišel k vam takoj, ko sem bil poklican. Sprašujem torej, zaradi kakšnega namena ste poslali pome?«',
        30: '§ In Kornelij je rekel: »Pred štirimi dnevi sem se postil do te ure. In ob deveti uri sem v svoji hiši molil in glej, pred menoj je stal mož v svetlem oblačilu.',
        31: 'In rekel: ›Kornelij, tvoja molitev je uslišana in tvoje miloščine so v spominu v Božjih očeh.',
        32: '§ Pošlji torej v Jopo in pokliči sèm Simona, katerega vzdevek je Peter. Nastanjen je ob morski obali, v hiši nekega strojarja Simona. Ko ta pride, ti bo spregovoril.‹',
        33: 'Takoj sem torej poslal pote in dobro si storil, da si prišel. Sedaj smo torej mi vsi tukaj zbrani pred Bogom, da slišimo vse stvari, ki so ti zapovedane od Boga.«',
        34: 'Tedaj je Peter odprl svoja usta in rekel: »Resnično zaznavam, da se Bog ne ozira na osebe,',
        35: 'temveč je v vsakem narodu pri njem sprejet, kdor se ga boji in dela pravično.',
        36: 'Besedo, ki jo je Bog poslal Izraelovim otrokom, ko je oznanjal mir po Jezusu Kristusu; (on je Gospod vsega),',
        37: 'to besedo, pravim, vi poznate, ki je bila razglašena po vsej celotni Judeji in se začela iz Galileje, po krstu, ki ga je oznanjal Janez.',
        38: 'Kako je Bog s Svetim Duhom in z močjo mazilil Jezusa iz Nazareta, ki je hodil okoli, delal dobro in ozdravljal vse, ki so bili zatirani od hudiča, kajti Bog je bil z njim.',
        39: 'In mi smo priče vseh stvari, ki jih je storil, tako v judovski deželi kakor v Jeruzalemu, ki so ga umorili in obesili na križ.',
        40: 'Njega je Bog tretji dan obudil in ga javno prikazal,',
        41: 'ne vsem ljudem, temveč od Boga vnaprej izbranim pričam, celó nam, ki smo z njim jedli in pili potem, ko je vstal od mrtvih.',
        42: 'In naročil nam je, naj oznanjamo ljudem in naj pričujemo, da je on tisti, ki je bil od Boga odrejen, da bo Sodnik živih in mrtvih.',
        43: 'Njemu vsi preroki dajejo pričevanje, da bo po njegovem imenu, kdorkoli veruje vanj, prejel odpuščanje grehov.«',
        44: 'Medtem ko je Peter še govoril te besede, je Sveti Duh padel na vse te, ki so slišali besedo.',
        45: 'In tisti iz obreze, ki so verovali, so bili osupli, kolikor jih je prišlo s Petrom, zato ker je bil dar Svetega Duha izlit tudi na pogane.',
        46: 'Kajti slišali so jih govoriti z jeziki in poveličevati Boga. Potem je Peter odgovoril:',
        47: '»Ali more kdorkoli prepovedati vodo, da ti, ki so enako kakor mi, prejeli Svetega Duha, ne bi bili krščeni?«',
        48: '§ In naročil jim je, naj jih krstijo v Gospodovem imenu. Potem so ga prosili, naj ostane nekaj dni.',
    },
    11: {
        1: 'Apostoli in bratje, ki so bili v Judeji, pa so slišali, da so tudi pogani sprejeli Božjo besedo.',
        2: 'In ko je Peter prišel gor v Jeruzalem, so se tisti, ki so bili iz obreze, pričkali z njim,',
        3: 'rekoč: »Odšel si k neobrezanim ljudem in jedel z njimi.«',
        4: 'Toda Peter jim je zadevo ponovil od začetka in jim jo po vrsti pojasnil, rekoč:',
        5: '»Bil sem v mestu Jopa in molil in v zamaknjenju sem videl videnje: ›Neka posoda se je spuščala, kot bi bil to velik prt, s štirimi vogali spuščan dol iz neba in ta je prišel celó do mene.',
        6: '§ Na katerem sem, ko sem [vanj] uprl svoje oči, opazoval in zagledal štirinožne zemeljske živali in divje zveri in plazeče stvari ter perjad neba.',
        7: 'In zaslišal sem glas, ki mi je rekel: ›Vstani, Peter, zakolji in jej.‹‹',
        8: 'Vendar sem rekel: ›Ne tako, Gospod, kajti v moja usta nikoli ni vstopilo nič oskrunjenega ali nečistega.‹',
        9: 'Toda glas iz neba mi je ponovno odgovoril: ›Kar je Bog očistil, tega ne imenuj oskrunjeno.‹',
        10: 'To pa se je zgodilo trikrat in vse je bilo ponovno dvignjeno v nebo.',
        11: 'In glej, takoj so bili tam trije možje, poslani k meni iz Cezareje, [ki so] že prišli k hiši, kjer sem bil.',
        12: 'In Duh mi je zaukazal, naj grem z njimi, ne da bi kaj dvomil. Poleg tega me je spremljalo teh šest bratov in vstopili smo v moževo hišo',
        13: 'in razložil nam je, kako je v svoji hiši videl angela, ki je stal ter mu rekel: ›Pošlji može v Jopo in pokliči Simona, katerega vzdevek je Peter,',
        14: 'ki ti bo povedal besede, po katerih boš rešen ti in vsa tvoja hiša.‹',
        15: 'In ko sem začel govoriti, je nanje padel Sveti Duh, kakor v začetku na nas.',
        16: 'Potem sem se spomnil Gospodove besede, kako je rekel: ›Janez je zares krščeval z vodo, toda vi boste krščeni s Svetim Duhom.‹',
        17: 'Torej jim je tedaj Bog dal podoben dar, kakor ga je dal nam, ki smo verovali v Gospoda Jezusa Kristusa. Kaj sem bil jaz, da bi se mogel zoperstaviti Bogu?«',
        18: 'Ko so slišali te stvari, so molčali in slavili Boga, rekoč: »Torej je Bog tudi poganom zagotovil kesanje v življenje.«',
        19: 'Torej tisti, ki so bili razkropljeni naokoli zaradi preganjanja, ki je nastalo okoli Štefana, so potovali prav do Fenikije in Cipra in Antiohije in nikomur niso oznanjali besede, razen samo Judom.',
        20: 'Nekateri izmed teh pa so bili možje s Cipra in Cirene, ki so, ko so prišli v Antiohijo, govorili Grkom ter oznanjali Gospoda Jezusa.',
        21: 'In Gospodova roka je bila z njimi, in veliko število [jih] je verovalo ter se spreobrnilo h Gospodu.',
        22: 'Potem so besede o teh stvareh prišle do ušes cerkve, ki je bila v Jeruzalemu, in poslali so naprej Barnaba, da bi šel prav do Antiohije.',
        23: 'Kateri, ko je prišel in videl Božjo milost, je bil vesel in vse spodbujal, da bi se s srčnim namenom trdno držali Gospoda.',
        24: 'Kajti bil je dober človek ter poln Svetega Duha in vere. In mnogo ljudi je bilo dodanih h Gospodu.',
        25: 'Potem se je Barnaba odpravil v Tarz, da poišče Savla,',
        26: 'in ko ga je našel, ga je privedel v Antiohijo. In pripetilo se je, da sta se celo leto zbirala s cerkvijo ter učila mnogo ljudi. In učenci so bili v Antiohiji prvič imenovani kristjani.',
        27: 'In v teh dneh so prišli preroki iz Jeruzalema v Antiohijo.',
        28: 'In vstal je nekdo, po imenu Agab ter po Duhu kazal, da naj bi bilo veliko pomanjkanje po vsem celotnem svetu, ki se je zgodilo v dneh cesarja Klavdija.',
        29: 'Potem so bili učenci, vsak mož glede na svojo zmožnost, odločeni, da pošljejo pomoč bratom, ki prebivajo v Judeji,',
        30: 'kar so tudi storili in to po Barnabovih ter Savlovih rokah poslali starešinam.',
    },
    12: {
        1: 'Torej okoli tega časa je kralj Herod iztegnil svoje roke, da nadleguje nekatere iz cerkve.',
        2: 'In z mečem je ubil Jakoba, Janezovega brata.',
        3: 'Ker pa je videl, [da] je Judom to ugajalo, je še bolj nadaljeval, da zgrabi tudi Petra. (Takrat so bili dnevi nekvašenega kruha.)',
        4: '§ In ko ga je zgrabil, ga je vtaknil v ječo ter ga izročil štirim četvericam vojakov, da ga varujejo, ker ga je mislil po Veliki noči privesti k ljudem.',
        5: 'Peter je bil torej zadržan v ječi, toda cerkev je zanj brez prenehanja molila k Bogu.',
        6: 'In ko naj bi ga Herod privedel, je isto noč Peter spal med dvema vojakoma, privezan z dvema verigama, čuvaji pred vrati pa so stražili ječo.',
        7: 'In glej, Gospodov angel je prišel nad njega in svetloba je zasijala v ječi in Petra je udaril v stran ter ga dvignil, rekoč: »Hitro vstani.« In njegove verige so odpadle z njegovih rok.',
        8: 'In angel mu je rekel: »Opaši se in si poveži svoje sandale.« In tako je storil. In mu reče: »Ogrni svojo obleko okoli sebe in mi sledi.«',
        9: 'In odšel je ven ter mu sledil in ni vedel, da je bilo res, kar se je zgodilo po angelu, temveč je mislil, da je videl videnje.',
        10: 'Ko sta bila mimo prve in druge straže, sta prišla k velikim železnim vratom, ki vodijo v mesto, ki so se jima sama od sebe odprla in odšla sta ven ter šla skozi neko ulico in angel je nemudoma odšel od njega.',
        11: 'Ko je Peter prišel k sebi, je rekel: »Sedaj zagotovo vem, da je Gospod poslal svojega angela in me osvobodil iz Herodove roke ter pred vsem pričakovanjem ljudi izmed Judov.«',
        12: 'Ko pa je stvar preudaril, je prišel k hiši Marije, Janezove matere, katerega vzdevek je bil Marko, kjer so bili mnogi skupaj zbrani ter molili.',
        13: 'In ko je Peter potrkal na velika vhodna vrata, je prišla prisluhnit gospodična, po imenu Roda.',
        14: 'In ko je spoznala Petrov glas, zaradi veselja ni odprla velikih vrat, temveč je stekla noter ter povedala, kako pred velikimi vrati stoji Peter.',
        15: 'Oni pa so ji rekli: »Nora si.« Toda nenehno je zatrjevala, da je bilo točno tako. Tedaj so ji rekli: »To je njegov angel.«',
        16: 'Toda Peter je nenehno trkal in ko so odprli vrata ter ga zagledali, so bili osupli.',
        17: 'Vendar ko jim je z roko namignil, naj molčijo, jim je razodel, kako ga je Gospod privedel iz ječe. In rekel je: »Pojdite, oznanite te stvari Jakobu in bratom.« In odšel je in šel v drug kraj.',
        18: 'Torej brž, ko je bil dan, med vojaki ni bila majhna razvnetost, kaj je nastalo s Petrom.',
        19: 'In ko ga je Herod iskal in ga ni našel, je zaslišal čuvaje ter ukazal, da naj bi bili le-ti usmrčeni. In iz Judeje je odšel dol v Cezarejo ter ostal tam.',
        20: 'Herod pa je bil zelo jezen na te iz Tira in Sidóna, toda oni so soglasno prišli k njemu in ker so naredili Blasta, kraljevega glavnega dvornega upravitelja, za svojega prijatelja, so želeli mir, kajti njihova dežela je bila hranjena s pomočjo kraljeve dežele.',
        21: 'Na določen dan pa se je Herod oblekel v kraljevsko obleko, se usedel na svoj prestol ter jim naredil slovesen govor.',
        22: 'Ljudstvo [dežele] pa je vzklikalo, rekoč: »To je božji glas, ne pa od človeka.«',
        23: 'In takoj ga je udaril Gospodov angel, ker ni dal slave Bogu in pojeden je bil od črvov ter izročil duha.',
        24: 'Toda Božja beseda je rasla in se množila.',
        25: 'In ko sta izpolnila svojo službo, sta se Barnaba in Savel vrnila iz Jeruzalema ter s seboj vzela Janeza, katerega vzdevek je bil Marko.',
    },
    13: {
        1: 'Torej v cerkvi, ki je bila v Antiohiji, so bili določeni preroki in učitelji, kot Barnaba in Simeon, ki so ga imenovali Niger in Lukij iz Cirene in Manaén, ki je bil vzgojen s Herodom, vladarjem četrtinskega dela province ter Savel.',
        2: 'Medtem ko so služili Gospodu in se postili, je Sveti Duh rekel: »Oddvojite mi Barnaba in Savla za delo, kamor sem ju poklical.«',
        3: 'In ko so se postili ter molili in svoje roke položili nanju, so ju odposlali.',
        4: 'Tako sta, odposlana po Svetem Duhu, odšla v Selevkíjo in od tam sta odjadrala na Ciper.',
        5: 'In ko sta bila v Salamini, sta v judovskih sinagogah oznanjala Božjo besedo in za svojo službo sta imela tudi Janeza.',
        6: 'In ko sta šla prek otoka do Pafosa, sta našla nekega čarodeja, lažnega preroka, Juda, katerega ime je bilo Barjezus,',
        7: 'ki je bil z namestnikom dežele, Sergijem Pavlom, razsodnim človekom, ki je dal poklicati Barnaba in Savla ter želel slišati Božjo besedo.',
        8: 'Toda čarodej Elíma (kajti takšno je po razlagi njegovo ime), se jima je zoperstavil ter si prizadeval namestnika odvrniti od vere.',
        9: 'Potem je Savel (ki se imenuje tudi Pavel), izpolnjen s Svetim Duhom, svoje oči uprl vanj',
        10: 'in rekel: »Oh poln vseh premetenosti in vseh vragolij, ti hudičev otrok, ti sovražnik vse pravičnosti, ali ne boš prenehal izkrivljati Gospodovih ravnih poti?',
        11: 'In sedaj glej, Gospodova roka je nad teboj in oslepel boš ter za nekaj časa ne boš videl sonca.« In takoj sta padla nanj zamegljenost in tema in krožil je ter iskal nekoga, da ga vodi za roko.',
        12: 'Potem je namestnik, ko je videl, kaj se je zgodilo, veroval in bil osupel nad Gospodovim naukom.',
        13: 'Torej ko so Pavel in njegova skupina odpluli iz Pafosa, so prišli v Pergo v Pamfiliji. Janez pa se je ločil od njiju in se vrnil v Jeruzalem.',
        14: 'Toda ko sta se odpravila iz Perge, sta prišla v Antiohijo v Pizidiji in na šabatni dan odšla v sinagogo ter se usedla.',
        15: 'Po branju postave in prerokov pa so predstojniki sinagoge poslali ponju, rekoč: » Vidva moža in brata, če imata kako spodbudno besedo za ljudi, povejta.«',
        16: 'Tedaj je Pavel vstal in s svojo roko dal znamenje ter rekel: »Možje Izraelci in vi, ki se bojite Boga, poslušajte.',
        17: 'Bog teh ljudi iz Izraela je izbral naše očete in povišal ljudi, ko so kot tujci prebivali v egiptovski deželi in jih s povzdignjenim laktom privedel ven iz nje.',
        18: 'In približno okoli štirideset let je prenašal njihovo obnašanje v divjini.',
        19: 'In ko je v kánaanski deželi uničil sedem narodov, jim je njihovo deželo razdelil z žrebom.',
        20: 'Nató pa jim je dajal sodnike za približno štiristo petdeset let, do preroka Samuela.',
        21: 'In zatem so zahtevali kralja in Bog jim je dal Savla, Kiševega sina, moža iz Benjaminovega rodu, za približno štirideset let.',
        22: 'In ko ga je odstranil, jim je dvignil Davida, da bi bil njihov kralj, ki mu je dal tudi pričevanje ter rekel: ›Našel sem Davida, Jesejevega sina, moža po svojem lastnem srcu, ki bo izpolnil vso mojo voljo.‹',
        23: '§ Iz semena tega človeka je Bog, glede na svojo obljubo, Izraelu obudil Odrešenika, Jezusa,',
        24: 'ko je pred njegovim prihodom Janez oznanjal krst kesanja vsem ljudem iz Izraela.',
        25: 'In ko je Janez izpolnil svoj tek, je rekel: ›Kdo mislite, da sem jaz? Jaz nisem on. Toda glejte, za menoj prihaja nekdo, čigar čevljev z njegovih stopal nisem vreden odvezati.‹',
        26: 'Možje in bratje, otroci Abrahamove rase ter kdorkoli se med vami boji Boga, vam je poslana beseda te rešitve duš.',
        27: 'Kajti tisti, ki prebivajo v Jeruzalemu in njihovi vladarji, ker niso spoznali njega niti glasov prerokov, ki se berejo vsak šabatni dan, so jih izpolnili z njegovo obsodbo.',
        28: 'In čeprav na njem niso našli nobenega razloga za smrt, so od Pilata zahtevali, da naj bi bil umorjen.',
        29: 'In ko so izpolnili vse, kar je bilo pisano o njem, so ga sneli z lesa ter ga položili v mavzolej.',
        30: 'Toda Bog ga je obudil od mrtvih,',
        31: 'in mnogo dni so ga videli tisti, ki so prišli z njim iz Galileje v Jeruzalem, ki so njegove priče ljudem.',
        32: 'In mi vam razodevamo vesele novice, kako je to obljubo, ki je bila narejena očetom,',
        33: 'Bog izpolnil nam, njihovim otrokom, v tem, da je ponovno dvignil Jezusa, kakor je tudi pisano v drugem psalmu: ›Ti si moj Sin, danes sem te rodil.‹',
        34: 'In glede na to, da ga je obudil od mrtvih, sedaj ni več vrnitve k trohnenju, je rekel na ta način: ›Dal vam bom zanesljive Davidove milosti.‹',
        35: 'Zato tudi pravi v še enem psalmu: ›Svojemu Svetemu ne boš dal videti trohnenja.‹',
        36: 'Kajti David je, potem ko je po Božji volji služil svojemu lastnemu rodu, zaspal in bil položen k svojim očetom ter videl trohnenje,',
        37: 'toda ta, ki ga je Bog ponovno obudil, ni videl trohnenja.',
        38: 'Naj bo torej znano vam, možje in bratje, da se vam po tem človeku oznanjuje odpuščanje grehov,',
        39: 'in po njem ste vsi, ki verujete, opravičeni vseh stvari, od katerih niste mogli biti opravičeni po Mojzesovi postavi.',
        40: 'Pazite se torej, da ne pride nad vas to, o čemer je govora v prerokih:',
        41: '›Glejte, vi prezirljivci in čudite se ter izginite, kajti v vaših dneh delam delo, delo katerega nikakor ne boste verovali, četudi vam ga človek razodene.‹«',
        42: '§ In ko so Judje odšli iz sinagoge, so pogani prosili, da bi jim bile te besede lahko oznanjene naslednjo šabat.',
        43: 'Torej ko je bila skupnost razpuščena, so mnogi izmed Judov in religioznih spreobrnjencev sledili Pavlu in Barnabu, ki sta jim govorila in jih prepričevala naj nadaljujejo v Božji milosti.',
        44: 'Naslednji šabatni dan pa je prišlo skupaj skoraj celotno mesto, da sliši Božjo besedo.',
        45: 'Toda ko so Judje videli množice, so bili izpolnjeni z zavistjo in ugovarjali ter preklinjali in govorili proti tem stvarem, ki jih je govoril Pavel.',
        46: 'Tedaj sta Pavel in Barnaba postala pogumna in rekla: »Potrebno je bilo, da bi se Božja beseda najprej spregovorila vam, toda ker ste jo postavili proč od sebe in sebe sodite nevredne večnega življenja, glejte, se obračava k poganom.',
        47: 'Kajti tako nam je ukazal Gospod, rekoč: ›Postavil sem te, da bi bil svetloba poganom, da naj bi bil za rešitev duš do koncev zemlje.‹«',
        48: 'In ko so pogani to slišali, so bili veseli in slavili Gospodovo besedo; in kolikor jih je bilo odrejenih za večno življenje, je verovalo.',
        49: 'In Gospodova beseda je bila razglašena po vsem celotnem področju.',
        50: 'Toda Judje so razvneli predane in častitljive ženske ter vodilne može mesta ter dvignili preganjanje zoper Pavla in Barnaba ter ju izgnali iz svojih krajev.',
        51: 'Vendar sta proti njim otresla prah s svojih stopal in prišla v Ikónij.',
        52: 'Učenci pa so bili izpolnjeni z radostjo in s Svetim Duhom.',
    },
    14: {
        1: 'Pripetilo pa se je v Ikóniju, da sta oba skupaj odšla v judovsko sinagogo in tako govorila, da je velika množica, tako Judov kakor tudi Grkov, verovala.',
        2: 'Toda neverni Judje so razvneli pogane in hudobno vplivali na njihovo mišljenje proti bratom.',
        3: 'Ostala sta torej dolgo časa in pogumno govorila v Gospodu, ki je dal pričevanje k besedi svoje milosti in zagotovil, da so se po njunih rokah dogajala znamenja in čudeži.',
        4: 'Vendar je bila množica iz mesta razdeljena; del je držal z Judi, del pa z apostoli.',
        5: 'In ko je bil storjen napad, ki so ga sprožili tako pogani kakor tudi Judje s svojimi vladarji, da z njima kruto ravnajo in da ju kamnajo,',
        6: 'sta bila o tem obveščena in pobegnila v Listro in Derbo, mesti v Likaoniji in k področju, ki leži naokoli',
        7: 'in tam oznanjala evangelij.',
        8: 'In v Listri je sedel nek mož, nemočen v svojih stopalih, pohabljen že od maternice svoje matere, ki nikoli ni hodil.',
        9: 'Isti je slišal Pavla govoriti. Ta je neomajno zrl vanj in zaznavajoč, da je imel vero, da bi bil ozdravljen,',
        10: 'je z močnim glasom rekel: »Stopi pokonci na svoja stopala.« In poskočil je in hodil.',
        11: 'In ko je množica videla, kaj je Pavel storil, so povzdignili svoje glasove, rekoč v likaonskem jeziku: »K nam dol sta prišla bogova v človeški podobi.«',
        12: 'In Barnaba so imenovali Jupitra, Pavla pa Merkurja, ker je bil glavni govornik.',
        13: 'Potem je Jupitrov svečenik, ki je bil pred njihovim mestom, k velikim vratom privedel vola in vence in z množico želel opraviti žrtvovanje.',
        14: 'Nakar, ko sta apostola Barnaba in Pavel to slišala, sta razparala svoja oblačila in stekla med množico, vzklikajoč',
        15: 'in govoreč: »Možje, zakaj počnete te stvari? Tudi midva sva z vami človeka podobnih strasti in oznanjava vam, da naj bi se od teh ničevosti obrnili k živemu Bogu, ki je naredil nebo in zemljo in morje ter vse stvari, ki so v njih,',
        16: 'ki je v prejšnjih časih prenašal vse narode, da hodijo po svojih lastnih poteh.',
        17: 'Vendar sebe ni pustil brez pričevanja, ker je delal dobro in nam dajal dež z neba ter rodovitna obdobja in naša srca napolnjeval s hrano in veseljem.«',
        18: 'In s temi besedami sta komaj zadržala množico, da jima ni opravila žrtvovanja.',
        19: 'In tja so prišli neki Judje iz Antiohije in Ikónija, ki so pregovorili množico in ko so kamnali Pavla, so ga izvlekli iz mesta, ker so mislili, da je bil mrtev.',
        20: 'Vendar ko so ga obkrožili učenci, je vstal ter prišel v mesto in naslednji dan z Barnabom odšel v Derbo.',
        21: 'In ko sta temu mestu oznanila evangelij ter mnoge učila, sta se ponovno vrnila v Listro in v Ikónij in Antiohijo',
        22: 'ter krepila duše učencev in jih spodbujala, naj nadaljujejo v veri in da moramo skozi veliko stisko vstopiti v Božje kraljestvo.',
        23: 'In ko sta jim v vsaki cerkvi odredila starešine ter molila s postom, sta jih priporočila Gospodu, ki so mu verovali.',
        24: 'In potem, ko sta prepotovala skozi vso Pizidijo, sta prišla v Pamfilijo.',
        25: 'In ko sta besedo oznanila v Pergi, sta odšla dol v Atálejo',
        26: 'in od tam sta odjadrala v Antiohijo, od koder sta bila priporočena Božji milosti za delo, ki sta ga izvršila.',
        27: 'In ko sta prišla in so skupaj zbrali cerkev, sta jim ponovila vse, kar je Bog z njima storil in kako je odprl vrata vere k poganom.',
        28: 'In tam sta z učenci ostala dolgo časa.',
    },
    15: {
        1: 'Neki ljudje, ki so prišli dol iz Judeje, pa so učili brate in govorili: »Razen če ne boste obrezani po Mojzesovem običaju, ne morete biti rešeni.«',
        2: 'Ko sta imela torej Pavel in Barnaba z njimi ne majhno razhajanje mnenj ter se z njimi pričkala, so odločili, da naj bi glede tega vprašanja Pavel in Barnaba ter nekateri drugi izmed njih šli gor v Jeruzalem, k apostolom in starešinam.',
        3: 'In na njihovo pot spremljani s cerkvijo, so šli skozi Fenikijo in Samarijo in razglašali spreobrnitev poganov in vsem bratom so napravili veliko radost.',
        4: 'In ko so prišli v Jeruzalem, so bili sprejeti od cerkve in od apostolov ter starešin in razglasili so vse stvari, ki jih je Bog z njimi storil.',
        5: 'Toda vstali so nekateri iz ločine farizejev, ki so verovali, rekoč: »Da jih je treba obrezati in jim naročiti, naj se držijo Mojzesove postave.«',
        6: 'In apostoli in starešine so prišli skupaj, da preudarijo o tej besedi.',
        7: 'In ko je bilo mnogo razpravljanja, je vstal Peter ter jim rekel: »Možje in bratje, vi veste, kako to, da je Bog pred davnim časom naredil med nami izbiro, da naj bi pogani po mojih ustih slišali besedo evangelija in verovali.',
        8: 'In Bog, ki pozna srca, jim pričuje, ker jim daje Svetega Duha, prav tako kakor je storil nam',
        9: 'in ni naredil nobene razlike med nami ter njimi, ko je po veri očistil njihova srca.',
        10: 'Zakaj torej zdaj skušate Boga, da nadenete na vrat učencev jarem, ki ga niti naši očetje niti mi nismo mogli nositi?',
        11: 'Ampak mi verujemo, da bomo rešeni po milosti Gospoda Jezusa Kristusa, prav tako kakor oni.«',
        12: 'Potem je vsa množica molčala in poslušala Barnaba in Pavla, ki sta razglašala, kakšne čudežne moči in čudeže je po njiju Bog storil med pogani.',
        13: 'In potem, ko so molčali, je Jakob odgovoril, rekoč: »Možje in bratje, prisluhnite mi.',
        14: 'Simeon je povedal, kako je Bog najprej obiskal pogane, da vzame izmed njih ljudi za svoje ime.',
        15: 'In k temu se ujemajo besede prerokov, kakor je pisano:',
        16: '›Po tem se bom vrnil in ponovno zgradil Davidovo šotorsko svetišče, ki je padlo in ruševine le-tega bom ponovno zgradil in jaz ga bom ponovno postavil,',
        17: 'da bi lahko preostanek ljudi iskal Gospoda in vsi pogani, nad katere je klicano moje ime, govori Gospod, ki dela vse te stvari.‹',
        18: 'Bogu so vsa njegova dela znana od začetka sveta.',
        19: 'Zatorej je moja razsodba, da ne vznemirjamo teh, ki so se iz poganstva obrnili k Bogu,',
        20: 'temveč, da jim napišemo, da se vzdržijo pred oskrunitvijo od malikov in pred prešuštvom in pred zadavljenimi stvarmi in pred krvjo.',
        21: 'Kajti Mojzes ima od starih časov v vsakem mestu tiste, ki ga oznanjajo, beroč vsak šabatni dan v sinagogah.«',
        22: 'Tedaj je apostolom in starešinam s celotno cerkvijo to ugajalo, da s Pavlom in Barnabom pošljejo v Antiohijo izbrana moža iz svoje lastne skupine; namreč Juda, imenovanega z vzdevkom Bársaba in Sila, vodilna moža med brati.',
        23: 'In po njiju so napisali pisma na ta način: ›Apostoli, starešine in bratje pošiljamo pozdrave bratom, ki so izmed poganov v Antiohiji in Siriji ter Kilikiji,',
        24: '§ ker smo slišali, da so vas nekateri, ki so odšli izmed nas, vznemirjali z besedami in spodkopavali vaše duše, rekoč: ›Vi morate biti obrezani in se držati postave,‹ katerim nismo dali nobene takšne zapovedi.',
        25: 'Nam, ki smo soglasno zbrani, se zdi dobro, da z našima ljubljenima Barnabom in Pavlom pošljemo k vam izbrana moža,',
        26: 'moža, ki sta svoja življenja tvegala zaradi imena našega Gospoda Jezusa Kristusa.',
        27: 'Poslali smo torej Juda in Sila, ki vam bosta iste stvari povedala ustno.',
        28: 'Kajti Svetemu Duhu in nam se zdi dobro, da vam ne nalagamo večjega bremena kakor te potrebne stvari:',
        29: 'da se vzdržite pred hrano, darovano malikom in pred krvjo in pred zadavljenimi stvarmi ter pred prešuštvom. Če sebe obvarujete pred njimi, boste storili v redu. Mnogo uspeha.‹',
        30: 'Torej ko so bili odposlani, so prišli v Antiohijo in ko so skupaj zbrali množico, so izročili poslanico,',
        31: 'katere so se, zaradi tolažbe, ko so jo brali, razveselili.',
        32: 'Juda in Sila, ki sta bila tudi sama preroka, pa sta brate z mnogimi besedami spodbujala in jih krepila.',
        33: 'In potem, ko sta se kratek čas mudila tam, sta od bratov v miru odšla k apostolom.',
        34: '§ Vendar je Sili ugajalo, da še ostane tam.',
        35: 'Tudi Pavel in Barnaba sta prav tako nadaljevala z mnogimi drugimi v Antiohiji in učila ter oznanjala Gospodovo besedo.',
        36: 'Nekaj dni kasneje je Pavel rekel Barnabu: »Pojdiva ponovno in obiščiva naše brate v vsakem mestu, kjer sva oznanjala Gospodovo besedo in poglejva, kako so.«',
        37: 'In Barnaba se je odločil, da s seboj vzameta Janeza, katerega vzdevek je bil Marko.',
        38: 'Toda Pavlu se ni zdelo dobro z njima vzeti tistega, ki je iz Pamfilije odšel od njiju in z njima ni odšel na delo.',
        39: 'Spor med njima pa je bil tako oster, da sta se ločila narazen drug od drugega. In tako je Barnaba vzel Marka ter odjadral na Ciper,',
        40: 'Pavel pa je izbral Sila in odšel, od bratov priporočen Božji milosti.',
        41: 'In odšel je skozi Sirijo in Kilikijo in krepil cerkve.',
    },
    16: {
        1: 'Potem je prišel v Derbe in Listro. In glej, tam je bil nek učenec, po imenu Timótej, sin neke ženske, ki je bila Judinja in je verovala, toda njegov oče je bil Grk,',
        2: 'ki je bil pri bratih, ki so bili v Listri in Ikóniju, na dobrem glasu.',
        3: 'Njega je Pavel hotel vzeti s seboj in vzel ga je ter ga obrezal zaradi Judov, ki so bili v teh četrtih, kajti vsi so vedeli, da je bil njegov oče Grk.',
        4: 'In ko so šli skozi mesta, so jim izročali odloke, da se jih držijo, ki so bili odrejeni od apostolov in starešin, ki so bili v Jeruzalemu.',
        5: 'In tako so bile cerkve utrjene v veri in so številčno dnevno naraščale.',
        6: 'Torej ko so šli skozi Frigijo in področje Galacije in jim je Sveti Duh prepovedal oznanjati besedo v Aziji,',
        7: '§ so potem, ko so prišli do Mízije, poskušali iti v Bitinijo, toda Duh jim ni dovolil.',
        8: 'In šli so mimo Mízije in se spustili do Troáde.',
        9: 'Ponoči pa se je Pavlu prikazalo videnje: »Tam je stal Makedonec in ga prosil, rekoč: ›Pridi sem v Makedonijo in nam pomagaj.‹«',
        10: 'In po tem, ko je imel videnje, smo si takoj prizadevali iti v Makedonijo, ker smo brez dvoma sklepali, da nas je poklical Gospod, da jim oznanimo evangelij.',
        11: 'Zato smo, ko smo dvignili sidro iz Troáde, prispeli z ravno smerjo v Samotrake in naslednjega dne v Neápolo',
        12: 'in od tam v Filípe, ki je glavno mesto tega dela Makedonije ter [rimska] kolonija. In v tem mestu smo prebivali nekaj dni.',
        13: 'In na šabat smo odšli iz mesta k bregu reke, kjer je bila običajno molitev in se usedli ter govorili ženskam, ki so tja zahajale.',
        14: 'In neka ženska, po imenu Lidija, prodajalka škrlata, iz mesta Tiatira, ki je oboževala Boga, nas je poslušala, katere srce je Gospod odprl, da je prisluhnila besedam, ki jih je govoril Pavel.',
        15: 'In ko je bila krščena ona in njena družina, nas je rotila, rekoč: »Če ste me presodili, da sem zvesta Gospodu, pridite v mojo hišo in ostanite tam.« In primorala nas je.',
        16: 'In pripetilo se je, ko smo šli k molitvi, da nas je srečala neka gospodična, obsedena z duhom vedeževanja, ki je z napovedovanjem usode prinašala veliko dobička svojim gospodarjem.',
        17: 'Ta je sledila Pavlu in nam ter vpila, rekoč: »Ti ljudje so služabniki Boga najvišjega, ki nam kažejo pot rešitve duš.«',
        18: 'In to je počela mnogo dni. Toda Pavel se je užaloščen obrnil in duhu rekel: »Zapovedujem ti v imenu Jezusa Kristusa, da prideš iz nje.« In še isto uro je prišel ven.',
        19: 'In ko so njeni gospodarji videli, da je izginilo upanje na njihov dobiček, so ujeli Pavla in Sila ter ju zvlekli na trg k vladarjem',
        20: 'in ju privedli k oblastnikom, rekoč: »Ta moža, ki sta Juda, delata našemu mestu silne težave',
        21: '§ ter učita običaje, ki za nas, ki smo Rimljani, niso zakoniti za sprejetje niti za obeleževanje.«',
        22: 'In množica je skupaj vstala proti njima in oblastniki so jima raztrgali njuna oblačila ter ukazali naj ju pretepejo.',
        23: 'In ko so nanju položili mnogo udarcev z bičem, so ju vrgli v ječo ter ječarju ukazali, naj ju varno straži.',
        24: 'Ta ju je, ker je prejel tak ukaz, pahnil v notranjo ječo in njuna stopala pričvrstil v kladi.',
        25: 'Ob polnoči pa sta Pavel in Sila molila ter pela hvalnice Bogu, jetniki pa so ju poslušali.',
        26: 'In nenadoma je bil močan potres, tako da so bili zamajani temelji ječe in takoj so se vsa vrata odprla in vezi vseh so bile odvezane.',
        27: 'In čuvaj ječe, ki se je prebudil iz svojega spanja in videl vrata ječe odprta, je izvlekel svoj meč in se hotel ubiti, ker je mislil, da so jetniki pobegnili.',
        28: 'Toda Pavel je z močnim glasom zaklical, rekoč: »Ne stôri si ničesar hudega, kajti vsi smo tukaj.«',
        29: 'Ta je potem zahteval luč in skočil noter in drhteč prišel ter padel dol pred Pavla in Sila',
        30: 'in ju privedel ven ter rekel: »Gospoda, kaj moram storiti, da bom rešen?«',
        31: 'In onadva sta rekla: »Veruj v Gospoda Jezusa Kristusa in rešen boš ti in tvoja hiša.«',
        32: 'In Gospodovo besedo sta govorila njemu in vsem, ki so bili v njegovi hiši.',
        33: 'In še isto uro noči ju je vzel ter umil njune udarce in nemudoma je bil krščen on in vsi njegovi.',
        34: 'In ko ju je privedel v svojo hišo, je pred njiju postavil jed ter se veselil, ker je z vso svojo hišo veroval v Boga.',
        35: 'In ko je bil dan, so oblastniki poslali narednike, rekoč: »Izpusti tista človeka.«',
        36: 'In čuvaj ječe je te besede povedal Pavlu: »Oblastniki so poslali, naj vaju izpustim. Sedaj torej odidita in pojdita v miru.«',
        37: 'Vendar jim je Pavel rekel: »Naju, ki sva Rimljana, so neobsojena javno pretepli in naju vrgli v ječo. In sedaj naju mečejo ven na skrivaj? Ne, resnično, temveč naj sami pridejo in naju spravijo ven.«',
        38: 'In naredniki so te besede povedali oblastnikom in ko so slišali, da sta bila Rimljana, so se zbali.',
        39: 'In prišli so ter ju rotili in ju privedli ven ter od njiju želeli, da odideta iz mesta.',
        40: 'In odšla sta iz ječe ter vstopila v Lidijino hišo; in ko sta videla brate, sta jih potolažila ter odšla.',
    },
    17: {
        1: 'Torej ko sta šla skozi Amfípolo in Apolonijo sta prišla do Tesaloníke, kjer je bila judovska sinagoga.',
        2: 'In kakor je bila njegova navada, je Pavel vstopil k njim in tri šabatne dneve z njimi razpravljal iz pisem,',
        3: 'razkrival in trdil, da je Kristus brezpogojno moral trpeti in ponovno vstati od mrtvih in da je ta Jezus, ki vam ga oznanjam, Kristus.',
        4: 'In nekateri izmed njih so verovali in se družili s Pavlom in Silom, in velika množica izmed predanih Grkov ter ne malo izmed vodilnih žensk.',
        5: 'Toda Judje, ki niso verovali, so prevzeti z zavistjo, vzeli k sebi neke ničvredne pajdaše iz prostaške sorte in zbrali skupino in po vsem mestu zanetili vstajo ter napadli Jazonovo hišo in si prizadevali, da ju privedejo k ljudstvu [dežele].',
        6: 'Ko pa ju niso našli, so Jazona in neke brate odvlekli k vladarjem mesta ter kričali: »Tile, ki so obrnili svet na glavo, so prišli tudi sèm,',
        7: 'ki jih je sprejel Jazon, in vsi ti delajo nasprotno cesarjevim odlokom, rekoč, da obstaja drug kralj, nek Jezus.«',
        8: 'In vznemirili so množico in mestne vladarje, ko so slišali te stvari.',
        9: 'In ko so od Jazona in od drugih prejeli varščino, so jih izpustili.',
        10: 'In bratje so Pavla ter Sila takoj ponoči odposlali v Berójo. Ko sta prispela tja, sta odšla v judovsko sinagogo.',
        11: 'Ti so bili plemenitejši, kakor tisti v Tesaloníki, ker so z vso prisebnostjo sprejeli besedo in dnevno preiskovali pisma, če so bile te stvari take.',
        12: 'Zato so mnogi izmed njih verovali, tudi častitljive ženske, ki so bile Grkinje in izmed mož ne malo.',
        13: 'Toda ko so Judje iz Tesaloníke spoznali, da je Pavel Božjo besedo oznanjal v Beróji, so prišli tudi tja in razvneli množico.',
        14: 'In potem so bratje Pavla takoj odposlali, da gre, kot bi bilo k morju, toda Sila in Timótej sta še vedno ostala tam.',
        15: 'In ti, ki so spremljali Pavla, so ga privedli v Atene in ko so prejeli zapoved za Sila in Timóteja, naj z vso naglico prideta k njemu, so odšli.',
        16: 'Torej medtem ko je Pavel v Atenah čakal nanju, je bil njegov duh v njem razvnet, ko je videl mesto v celoti predano malikovanju.',
        17: 'Zato se je v sinagogi prerekal z Judi in s predanimi osebami in vsakodnevno na trgu s temi, ki so se srečevali z njim.',
        18: '§ Potem so mu ugovarjali neki filozofi izmed epikurejcev in izmed stoikov. In nekateri so rekli: »Kaj hoče povedati ta blebetavec?« Drugi nekako: »Zdi se, da je oznanjevalec tujih bogov,« ker jim je oznanjal Jezusa in vstajenje.',
        19: 'In prijeli so ga ter ga privedli na Areopag, rekoč: »Ali lahko izvemo, kakšen je ta novi nauk, o katerem govoriš?«',
        20: 'Kajti v naša ušesa prinašaš nekatere čudne besede. Hočemo torej izvedeti, kaj te stvari pomenijo.',
        21: '(Kajti vsi Atenci in tujci, ki so bili tam, svojega časa niso porabljali za nič drugega, razen da so ali govorili ali poslušali kako novo stvar.)',
        22: '§ Tedaj je Pavel na sredi Marsovega hriba vstal in rekel: » Vi atenski možje, zaznavam, da ste v vseh stvareh preveč vraževerni.',
        23: 'Kajti ko sem šel mimo in gledal vaše predmete čaščenja, sem našel oltar s tem napisom: NEPOZNANEMU BOGU. Katerega torej vi nevedno obožujete, tega vam jaz razglašam.',
        24: 'Bog, ki je naredil svet in vse stvari na njem, glede na to, da je on Gospodar neba in zemlje, ne prebiva v templjih, narejenimi z rokami,',
        25: 'tudi ni oboževan s človeškimi rokami, kakor da karkoli potrebuje, glede na to, da vsem daje življenje in dihanje in vse stvari',
        26: 'in je iz ene krvi naredil vse narode ljudi, da prebivajo na vsem obličju zemlje in je vnaprej določil določene čase in meje njihovega prebivanja,',
        27: '§ da bi iskali Gospoda, če bi ga morda dotipali in ga našli, čeprav ni daleč od vsakega izmed nas.',
        28: 'Kajti v njem živimo in se gibljemo in obstajamo, kakor so rekli celó nekateri izmed vaših lastnih pesnikov: ›Kajti tudi mi smo njegovo potomstvo.‹',
        29: 'Kot smo torej zagotovo potomstvo Boga, ne bi smeli misliti, da je Božanstvo podobno zlatu ali srebru ali kamnu, vrezanemu od umetnika in [s] človeško pripravo.',
        30: 'In nad časi te nevednosti je Bog zamižal, toda sedaj povsod vsem ljudem zapoveduje, da se pokesajo,',
        31: 'kajti določil je dan, na katerega bo sodil svet v pravičnosti, po tem možu, ki ga je določil. O tem je dal zagotovilo vsem ljudem, ker ga je obudil od mrtvih.«',
        32: 'Ko pa so slišali o vstajenju mrtvih, so se nekateri posmehovali, drugi pa so rekli: »Oh tej zadevi te bomo ponovno poslušali.«',
        33: 'Tako je Pavel odšel izmed njih.',
        34: 'Vendar so se mu določeni možje trdno pridružili in verovali, med katerimi je bil Dionizij Areopagít in ženska, po imenu Dámaris in drugi z njima.',
    },
    18: {
        1: 'Po teh stvareh je Pavel odšel iz Aten in prišel v Korint',
        2: 'in našel nekega Juda po imenu Ákvila, rojenega v Pontu, [ki je] s svojo ženo Prískilo nedavno prišel iz Italije; (zato ker je Klavdij vsem Judom ukazal oditi iz Rima) in prišel k njima.',
        3: 'In ker je bil iste obrti, je ostal z njima in delal, kajti po njunem poklicu sta bila izdelovalca šotorov.',
        4: 'In vsak šabat je razpravljal v sinagogi in pregovarjal Jude ter Grke.',
        5: '§ In ko sta iz Makedonije prišla Sila in Timótej, je bil Pavel v duhu gnan in Judom pričeval, da Jezus je bil Kristus.',
        6: 'In ko so nasprotovali samim sebi in izrekali bogokletje, je otresel svoje oblačilo ter jim rekel: »Vaša kri naj bo na vaših lastnih glavah. Jaz sem čist. Odslej bom šel k poganom.«',
        7: '§ In odšel je od tam ter vstopil v hišo nekega moža, po imenu Just, nekoga, ki je oboževal Boga, čigar hiša je bila tik poleg shodnice.',
        8: 'In Krisp, glavni predstojnik sinagoge, je z vso svojo hišo veroval v Gospoda in mnogi izmed Korinčanov so ob poslušanju verovali in bili so krščeni.',
        9: 'Potem je ponoči v videnju Pavlu govoril Gospod: »Ne boj se, temveč govori in ne molči,',
        10: 'kajti jaz sem s teboj in nihče se ne bo spravil nadte, da te poškoduje, kajti v tem mestu imam veliko ljudi.«',
        11: 'In tam je nadaljeval leto in šest mesecev ter med njimi učil Božjo besedo.',
        12: 'In ko je bil namestnik Ahaje Galíon, so Judje proti Pavlu soglasno naredili upor in ga privedli k sodnemu stolu,',
        13: 'rekoč: »Ta pregovarja ljudi, da obožujejo Boga v nasprotju s postavo.«',
        14: 'In ko je Pavel že skoraj odprl svoja usta, je Galíon rekel Judom: »Če bi bil razlog krivična zadeva ali zlobna nespodobnost, oh vi Judje, bi vas bil voljan prenašati.',
        15: 'Toda če je to vprašanje besed in imen in vaše postave, vi glejte na to, kajti v teh zadevah ne bom sodnik.«',
        16: 'In spodil jih je od sodnega stola.',
        17: 'Tedaj so vsi Grki prijeli Sosténa, glavnega predstojnika sinagoge in ga pretepli pred sodnim stolom. Galíon pa se ni zmenil za nobeno od teh stvari.',
        18: 'In Pavel je po tem ostal tam še dolgo časa in se nató poslovil od bratov ter od tam odjadral v Sirijo in z njim Prískila in Ákvila, ko je v Kenhrejah ostrigel svojo glavo, kajti imel je zaobljubo.',
        19: 'In prišel je v Efez ter ju pustil tam, toda on sam je vstopil v sinagogo in razpravljal z Judi.',
        20: 'Ko so ga prosili, da ostane z njimi dlje časa, ni privolil,',
        21: '§ temveč se je poslovil, rekoč: »Vsekakor moram ta praznik, ki prihaja, praznovati v Jeruzalemu. Toda ponovno se bom vrnil k vam, če Bog hoče.« In odjadral je iz Efeza.',
        22: 'In ko je pristal v Cezareji in šel gor ter pozdravil cerkev, je odšel dol v Antiohijo.',
        23: 'In potem, ko je tam preživel nekaj časa, je odšel in se po vrsti odpravil preko vse dežele Galačanov in Frigije ter krepil vse učence.',
        24: 'In v Efez je prišel nek Jud, po imenu Apolo, rojen v Aleksandriji, zgovoren človek in mogočen v pismih.',
        25: 'Ta človek je bil poučen o Gospodovi poti. Ker pa je bil v duhu goreč, je govoril in marljivo učil stvari o Gospodu, poznavajoč samo Janezov krst.',
        26: 'In v sinagogi je začel pogumno govoriti. Ko sta ga Prískila in Ákvila slišala, sta ga vzela k sebi in mu podrobneje pojasnila Božjo pot.',
        27: 'In ko je bil pripravljen, da odide v Ahajo, so bratje pisali in spodbudili učence, da ga sprejmejo. Ko je prišel, je mnogo pomagal tem, ki so po milosti verovali,',
        28: 'kajti mogočno je prepričeval Jude in to javno in s pismi dokazoval, da je Jezus bil Kristus.',
    },
    19: {
        1: 'In pripetilo se je, medtem ko je bil Apolo v Korintu, da je Pavel, ko je šel skozi gornje kraje, prišel v Efez. In ko je našel nekatere učence,',
        2: 'jim je rekel: »Ali ste, odkar ste verovali, prejeli Svetega Duha?« Oni pa so mu rekli: »Mi smo komaj slišali, ali obstaja nek Sveti Duh.«',
        3: 'In rekel jim je: »V kaj ste bili tedaj krščeni?« In rekli so: »Z Janezovim krstom.«',
        4: 'Potem je Pavel rekel: »Janez je resnično krščeval s krstom kesanja, govoreč ljudem, da naj verujejo v tistega, ki naj bi prišel za njim, to je v Kristusa Jezusa.«',
        5: 'Ko so to slišali, so bili krščeni v imenu Gospoda Jezusa.',
        6: 'In ko je Pavel nanje položil svoje roke, je prišel nadnje Sveti Duh, in govorili so z jeziki ter prerokovali.',
        7: 'In vseh mož je bilo okoli dvanajst.',
        8: 'In odšel je v sinagogo in približno tri mesece pogumno govoril, razpravljal in prepričeval [o] stvareh glede Božjega kraljestva.',
        9: 'Toda ko so bili številni zakrknjeni in niso verovali, temveč so pred množico o tej poti govorili hudobno, je odšel od njih in oddvojil učence in dnevno razpravljal v šoli nekega Tirána.',
        10: 'In to se je nadaljevalo približno dve leti, tako da so vsi, ki so prebivali v Aziji, slišali besedo Gospoda Jezusa, tako Judje kakor Grki.',
        11: 'In Bog je po Pavlovih rokah delal posebne čudeže,',
        12: 'tako da so od njegovega telesa bolnim nosili robce ali predpasnike, in bolezni so odhajale od njih in zli duhovi so izhajali iz njih.',
        13: 'Takrat so se tudi nekateri potepuški Judje, izganjalci duhov, lotili klicati ime Gospoda Jezusa nad temi, ki so imeli zle duhove, rekoč: »Mi vas zaklinjamo pri Jezusu, ki ga oznanja Pavel.«',
        14: 'In bilo je sedem sinov nekega Skevá, Juda in vodilnega izmed duhovnikov, ki so to delali.',
        15: 'Zli duh pa je odgovoril in rekel: »Jezusa poznam in Pavla poznam, toda kdo ste vi?«',
        16: 'In človek, v katerem je bil zli duh, je skočil nanje ter jih premagal in prevladal proti njim, tako da so iz te hiše pobegnili nagi in ranjeni.',
        17: 'In to je postalo znano vsem Judom in Grkom, ki so prav tako prebivali v Efezu in strah se je spustil na vse [izmed] njih in ime Gospoda Jezusa je bilo poveličano.',
        18: 'In mnogi, ki so verovali, so prišli in priznali ter razodeli svoja dejanja.',
        19: 'Tudi mnogi izmed teh, ki so uporabljali magijo, so svoje knjige prinesli skupaj in jih sežgali pred vsemi ljudmi, in izračunali so njihovo vrednost ter ugotovili, [da] je petdeset tisoč koščkov srebra.',
        20: 'Tako je Božja beseda mogočno rasla in prevladala.',
        21: 'Ko so bile te stvari končane, se je Pavel v duhu namenil, ko je šel skozi Makedonijo in Ahajo, da gre do Jeruzalema, rekoč: »Potem ko sem bil tukaj, moram videti tudi Rim.«',
        22: 'Tako je v Makedonijo poslal dva izmed teh, ki so mu služili, Timóteja in Erásta, toda on sam je nekaj časa ostal v Aziji.',
        23: 'In hkrati je tam nastala ne majhna razvnetost glede te poti.',
        24: 'Kajti nek človek, po imenu Demetrij, srebrar, ki je izdeloval srebrne svetinje za Diano, ki so prinašale rokodelcem ne malo dobička,',
        25: 'ki jih je skupaj z delavci podobnega poklica sklical in rekel: »Gospodje, vi veste, da imamo od te obrti svoje premoženje.',
        26: 'Poleg tega vidite in slišite, da je, ne samo v Efezu, temveč skoraj po vsej celotni Aziji, ta Pavel prepričal in odvrnil mnogo ljudi, govoreč, da niso nikakršni bogovi, ki so narejeni z rokami,',
        27: 'tako da ni samo naša obrt v nevarnosti, da bo zaničevana, temveč, da naj bi bil preziran tudi tempelj velike boginje Diane in uničena naj bi bila njena veličastnost, ki jo obožuje vsa Azija in svet.«',
        28: 'In ko so slišali te besede, so bili polni besa in vpili, rekoč: »Velika je Diana Efeška.«',
        29: 'In celotno mesto je bilo napolnjeno z zmešnjavo. In ko so ujeli Gaja in Aristarha, moža iz Makedonije, Pavlova družabnika na potovanju, so z njima soglasno zdrveli v gledališče.',
        30: 'Ko pa je Pavel hotel vstopiti k ljudstvu [dežele], mu učenci niso dovolili.',
        31: 'Nekateri izmed azijskih voditeljev, ki so bili njegovi prijatelji, pa so poslali k njemu ter ga prosili, da sebe v gledališču ne bi izpostavljal.',
        32: 'Nekateri so torej vpili eno stvar, nekateri pa drugo, kajti zbor je bil zmeden in večji del ni vedel, zakaj so prišli skupaj.',
        33: 'In iz množice so potegnili Aleksandra, ki so ga Judje porivali naprej. In Aleksander je z roko dal znamenje in želel narediti svoj zagovor pred ljudstvom [dežele].',
        34: 'Vendar ko so spoznali, da je bil Jud, so vsi soglasno približno dve uri vpili: »Velika je Diana Efeška.«',
        35: 'In ko je mestni uradnik pomiril množico, je rekel: » Vi efeški možje, kateri človek tukaj ne ve, kako je mesto Efežanov oboževalec velike boginje Diane in podobe, ki je padla dol iz Jupitra?',
        36: 'Ker pa se torej zoper te stvari ne more govoriti, morate biti mirni in ne storite ničesar prenagljenega.',
        37: 'Kajti sèm ste privedli ta moža, ki nista niti roparja cerkvá niti nista bogokletnika vaše boginje.',
        38: 'Zatorej, če imajo Demetrij in rokodelci, ki so z njim, besedo proti kateremukoli človeku, je sodišče odprto in tam so namestniki; naj drug drugega tožijo.',
        39: 'Toda če karkoli povprašujete glede drugih zadev, bo to odločeno na zakonitem zboru.',
        40: 'Kajti v nevarnosti smo, da bi bili klicani na zagovor zaradi vstaje tega dne, kajti nobenega razloga ni, s čimer lahko damo obračun tega vrveža.«',
        41: '§ In ko je to rekel, je razpustil zbor.',
    },
    20: {
        1: 'In potem, ko je vstaja prenehala, je Pavel k sebi poklical učence ter jih objel in odšel, češ da gre v Makedonijo.',
        2: 'In ko je odšel preko teh krajev in jim dal mnogo spodbude, je prišel v Grčijo',
        3: 'in tam je ostal tri mesece. In ko so Judje prežali nanj, ko je že skoraj odplul v Sirijo, se je namenil vrniti preko Makedonije.',
        4: '§ In v Azijo so ga spremljali Sópater iz Beróje; in iz Tesaloníke Aristarh in Sekúndus; in Gaj iz Derbe in Timótej; in iz Azije Tihik in Trofim.',
        5: 'Ti, ki so šli pred nami, so nas pričakali v Troádi.',
        6: 'In po dneh nekvašenega kruha smo odjadrali iz Filípov in v petih dneh prišli k tem v Troádo, kjer smo ostali sedem dni.',
        7: 'In na prvi dan tedna, ko so učenci prišli skupaj k lomljenju kruha, jim je Pavel oznanjal, pripravljen, da jutri odide; in svoj govor nadaljeval do polnoči.',
        8: 'V zgornji sobi, kjer so bili skupaj zbrani, pa je bilo mnogo svetilk.',
        9: 'In na oknu je sedel nek mladenič, po imenu Evtih, ki je padel v globoko spanje. In medtem ko je Pavel dolgo pridigal, se je pogreznil v spanje in padel dol z [najvišjega], tretjega nadstropja in pobran je bil mrtev.',
        10: 'In Pavel je odšel dol, se zgrudil nanj, ga objel ter rekel: »Ne vznemirjajte se, kajti njegovo življenje je v njem.«',
        11: 'Ko je torej ponovno prišel gor in prelomil kruh in jedel ter še dolgo časa govoril, celó do svita, je tako odšel.',
        12: 'In mladeniča so privedli živega in bili so ne malo potolaženi.',
        13: 'In šli smo naprej k ladji in odjadrali do Asosa. Tam smo nameravali sprejeti Pavla, kajti tako je določil, ker je nameraval iti peš.',
        14: 'In ko se je z nami srečal pri Asosu, smo ga sprejeli in prišli v Mitiléno.',
        15: '§ In od tam smo odjadrali in naslednji dan prišli nasproti Hiosu. In naslednji dan smo prispeli v Samos in ostali v Trogilu. In naslednji dan smo prišli v Milet.',
        16: 'Kajti Pavel se je odločil, da jadra mimo Efeza, ker v Aziji ni želel porabiti časa, kajti hitel je, če bi mu bilo mogoče, da bo na binkoštni dan v Jeruzalemu.',
        17: 'In iz Mileta je poslal v Efez in poklical starešine cerkve.',
        18: 'In ko so prišli k njemu, jim je rekel: »Od prvega dne, ko sem prišel v Azijo, veste, na kakšen način sem bil z vami v vseh obdobjih',
        19: 'in služil Gospodu z vso ponižnostjo mišljenja ter z mnogimi solzami in preizkušnjami, ki so me doletele med prežanjem Judov,',
        20: 'in kako nisem ničesar zamolčal, kar vam je bilo koristno, temveč sem vam pokazal in vas javno učil ter od hiše do hiše',
        21: 'pričeval obojim, tako Judom kakor tudi Grkom, kesanje pred Bogom in vero v našega Gospoda Jezusa Kristusa.',
        22: 'In sedaj glejte, grem v Jeruzalem, zvezan v duhu in ne poznam stvari, ki me bodo tam doletele,',
        23: 'razen da Sveti Duh v vsakem mestu pričuje, rekoč, da me čakajo vezi in stiske.',
        24: '§ Toda nobena od teh besed me ne gane niti ne cenim svojega življenja dragocenega sebi, tako da bom lahko dokončal svoj tek z radostjo in službo, ki sem jo prejel od Gospoda Jezusa, da pričujem evangelij o Božji milosti.',
        25: 'In sedaj glejte, vem, da vi vsi, med katere sem odšel in oznanjal Božje kraljestvo, ne boste več videli mojega obraza.',
        26: 'Zaradi tega vam danes dajem izjavo, da sem čist pred krvjo vseh ljudi.',
        27: 'Kajti nisem se izogibal, da vam oznanim vso Božjo namero.',
        28: 'Zatorej pazite nase in na ves trop, nad katerim vas je Sveti Duh naredil nadzornike, da pasete Božjo cerkev, ki jo je pridobil s svojo lastno krvjo.',
        29: 'Kajti vem to, da bodo po mojem odhodu vstopili med vas nadležni volkovi, ki ne bodo prizanašali tropu.',
        30: 'Prav tako bodo izmed vas vstali možje, ki bodo govorili sprevržene besede, da učence odtegnejo za seboj.',
        31: 'Torej čujte in se spomnite, da v obdobju treh let, ponoči in podnevi, nisem prenehal s solzami vsakogar svariti.',
        32: 'In sedaj, bratje, vas priporočam Bogu in besedi njegove milosti, ki je zmožna, da vas izgradi in da vam da dediščino med vsemi temi, ki so posvečeni.',
        33: 'Nisem hlepel po nikogaršnjem srebru ali zlatu ali obleki.',
        34: 'Da, tudi vi sami veste, da so te roke služile mojim potrebam in tem, ki so bili z menoj.',
        35: 'Pokazal sem vam vse stvari, da moramo s takšnim trudom podpirati slabotne in se spominjati besed Gospoda Jezusa, kako je rekel: ›Bolj blagoslovljeno je dajati kakor prejemati.‹ «',
        36: 'In ko je tako govoril, je pokleknil in z njimi vsemi molil.',
        37: 'In vsi so bridko jokali in se oklenili Pavlovega vratu ter ga poljubljali',
        38: 'in žalovali predvsem zaradi vseh besed, ki jih je govoril, da naj ne bi več videli njegovega obraza. In pospremili so ga k ladji.',
    },
    21: {
        1: 'In pripetilo se je, da potem, ko smo odšli od njih in odrinili, smo z ravno smerjo prispeli na Kos in naslednji dan na Rodos in od tam v Pátaro,',
        2: 'in ko smo našli ladjo, ki je jadrala preko do Fenikije, smo se vkrcali in odpotovali.',
        3: 'Torej ko smo odkrili Ciper, smo ga pustili na levi roki in odjadrali v Sirijo ter pristali v Tiru, kajti tam je ladja iztovorila svoj tovor.',
        4: 'In ko smo našli učence, smo tam ostali sedem dni. Ti so Pavlu po Duhu povedali, da naj ne bi šel gor v Jeruzalem.',
        5: 'In ko smo te dneve dovršili, smo se odpravili in odšli [po] naši poti. In na našo pot so nas vsi pospremili z ženami in otroki, dokler nismo bili izven mesta, in pokleknili smo na obali ter molili.',
        6: 'In ko smo se poslovili drug od drugega, smo se odpeljali z ladjo, oni pa so se ponovno vrnili domov.',
        7: 'In ko smo dokončali naše potovanje iz Tira, smo prišli v Ptolemáido in pozdravili brate in en dan ostali z njimi.',
        8: 'In naslednji dan smo mi, ki smo bili iz Pavlove skupine, odšli ter prišli v Cezarejo in vstopili v hišo evangelista Filipa, ki je bil eden izmed sedmih; in ostali z njim.',
        9: 'In isti mož je imel štiri hčere, device, ki so prerokovale.',
        10: 'In ko smo se tam mudili mnogo dni, je prišel dol iz Judeje nek prerok, po imenu Agab.',
        11: 'In ko je prišel k nam, je vzel Pavlov pas ter si zvezal svoje lastne roke in stopala ter rekel: »Tako govori Sveti Duh: ›Tako bodo Judje v Jeruzalemu zvezali moža, ki ima v lasti ta pas in ga izročili v roke poganom.‹«',
        12: 'In ko smo slišali te stvari, smo ga rotili, tako mi kakor tudi tisti iz tega kraja, naj ne hodi gor v Jeruzalem.',
        13: 'Potem je Pavel odgovoril: »Kaj mislite, da jokate in da mi lomite moje srce? Pripravljen sem ne samo biti zvezan, temveč v Jeruzalemu tudi umreti za ime Gospoda Jezusa.«',
        14: 'In ko ni želel biti pregovorjen, smo prenehali, rekoč: »Zgôdi se Gospodova volja.«',
        15: 'In po teh dneh smo vzeli svojo prtljago in odšli gor v Jeruzalem.',
        16: '§ Z nami so šli tja tudi nekateri učenci iz Cezareje in s seboj so privedli nekega Mnazona iz Cipra, starega učenca, pri katerem naj bi prenočili.',
        17: 'In ko smo prišli v Jeruzalem, so nas bratje veselo sprejeli.',
        18: 'In naslednji dan je Pavel z nami odšel k Jakobu in prisotne so bile vse starešine.',
        19: 'In ko jih je pozdravil, je podrobno pojasnil, kakšne stvari je Bog po njegovi službi storil med pogani.',
        20: 'In ko so to slišali, so slavili Gospoda in mu rekli: »Vidiš, brat, kako mnogo tisočev Judov je tukaj, ki verujejo, in vsi so goreči za postavo,',
        21: 'o tebi pa so obveščeni, da vse Jude, ki so med pogani, učiš, da zapustijo Mojzesa, rekoč, da jim ni treba obrezati njihovih otrok niti živeti po običajih.',
        22: 'Kaj je to torej? Množica mora brezpogojno priti skupaj, kajti slišali bodo, da si prišel.',
        23: 'Pravimo ti, stôri torej tole: ›Imamo štiri može, ki imajo na sebi zaobljubo;',
        24: 'vzemi jih in se z njimi očisti in naj bodo tvoji stroški, da si bodo lahko obrili svoje glave, in vsi bodo lahko spoznali, da te stvari, o katerih so bili glede tebe obveščeni, niso nič, temveč da tudi sam živiš redno in se držiš postave.‹',
        25: '§ Kar zadeva pogane, ki verujejo, smo pisali in sklenili, da [naj] ne obeležujejo nobene takšne stvari, razen samo, da se varujejo pred stvarmi darovanim malikom in pred krvjo in pred zadavljenim in pred prešuštvom.«',
        26: 'Tedaj je Pavel vzel može in naslednji dan, ko se je očistil, je z njimi vstopil v tempelj, da naznani dovršitev dni očiščevanja, dokler se ne bi za vsakega izmed njih darovala daritev.',
        27: 'In ko se je sedem dni skoraj dokončalo, so Judje, ki so bili iz Azije, ko so ga zagledali v templju, razvneli vso množico in nanj položili roke',
        28: 'ter vzklikali: »Možje Izraelci, pomagajte: ›To je človek, ki povsod vse može uči proti ljudem in postavi ter temu kraju, in razen tega je tudi Grke privedel v tempelj in oskrunil ta sveti prostor.‹«',
        29: '(Kajti prej so v mestu videli z njim Efežana Trofima, za katerega so domnevali, da ga je Pavel privedel v tempelj.)',
        30: 'In vse mesto je bilo razdraženo in ljudje so tekli skupaj in prijeli so Pavla ter ga odvlekli iz templja in nemudoma so bila vrata zaprta.',
        31: 'In medtem ko so ga poskušali ubiti, so prišle k vrhovnemu poveljniku čete novice, da je bil ves Jeruzalem v vstaji.',
        32: 'Ki je takoj vzel vojake in stotnike ter stekel dol k njim. In ko so zagledali vrhovnega poveljnika in vojake, so Pavla prenehali pretepati.',
        33: 'Tedaj se je približal vrhovni poveljnik in ga prijel ter mu ukazal, naj bo zvezan z dvema verigama in zahteval je kdo je bil in kaj je storil.',
        34: 'In nekateri so med množico vpili eno stvar, nekateri drugo in ko ni mogel zanesljivo izvedeti gotovosti za hrup, je ukazal, da ga s seboj vzamejo v grad.',
        35: 'In ko je prišel na stopnice, je bilo tako, da so ga zaradi nasilja množice nesli vojaki.',
        36: 'Kajti množica ljudi je sledila za njimi in kričala: »Proč z njim.«',
        37: 'In ko naj bi bil Pavel odveden v grad, je vrhovnemu poveljniku rekel: »Ti smem spregovoriti?« Ki je rekel: »Znaš govoriti grško?',
        38: 'Ali nisi ti tisti Egipčan, ki je pred temi dnevi naredil vstajo in v divjino odvedel štiri tisoč mož, ki so bili morilci?«',
        39: 'Vendar je Pavel rekel: »Jaz sem človek, ki sem Jud iz Tarza, mesta v Kilikiji, meščan ne nepomembnega mesta, in rotim te, dovoli mi, da spregovorim ljudem.«',
        40: 'In ko mu je dal dovoljenje, je Pavel stal na stopnicah in z roko dal znamenje ljudem. In ko je nastala velika tišina, jim je spregovoril v hebrejskem jeziku, rekoč:',
    },
    22: {
        1: '»Možje, bratje in očetje, poslušajte moj zagovor, ki vam ga sedaj delam.«',
        2: '(In ko so slišali, da jim je spregovoril v hebrejskem jeziku, so ohranili še večjo tišino, in on reče):',
        3: '»Jaz sem resnično človek, ki sem Jud, rojen v Tarzu, mestu v Kilikiji, vendar vzgojen v tem mestu pri Gamálielovih stopalih in poučevan glede na popolne običaje postave očetov in bil sem goreč za Boga, kakor ste danes vi vsi.',
        4: 'In to pot sem preganjal do smrti ter zvezoval in izročal v ječe tako moške kakor ženske.',
        5: 'Kakor tudi véliki duhovnik pričuje o meni in vse visoke starešine, od katerih sem prav tako prejel pisma za brate in odšel v Damask, da privedem te, ki so bili tam, zvezane v Jeruzalem, da bi bili kaznovani.',
        6: 'In pripetilo se je, da ko sem bil na potovanju in sem okoli poldneva prišel blizu Damaska, je nenadoma okoli mene z neba zasijala močna svetloba.',
        7: 'In padel sem na tla ter zaslišal glas, ki mi je rekel: ›Savel, Savel, zakaj me preganjaš?‹',
        8: '§ In odgovoril sem: ›Kdo si ti, Gospod?‹ On pa mi je rekel: ›Jaz sem Jezus Nazarečan, ki ga ti preganjaš.‹',
        9: 'In tisti, ki so bili z menoj, so zares videli svetlobo in so bili prestrašeni, toda niso slišali glasu tistega, ki mi je govoril.',
        10: 'In rekel sem: ›Kaj naj storim, Gospod.‹ In Gospod mi je rekel: ›Vstani in pojdi v Damask in tam ti bo povedano o vseh stvareh, ki so ti določene, da jih storiš.‹',
        11: 'In ko zaradi slave te svetlobe nisem mogel videti, sem voden za roko teh, ki so bili z menoj, prišel v Damask.',
        12: 'In nek Hananija, glede na postavo predan mož, na dobrem glasu od vseh Judov, ki so prebivali tam,',
        13: 'je prišel k meni in se ustavil ter mi rekel: ›Brat Savel, prejmi svoj vid.‹ In isto uro sem pogledal nanj.',
        14: 'In rekel je: ›Bog naših očetov te je izbral, da bi spoznal njegovo voljo in vidiš tega Pravičnega in da bi slišal glas iz njegovih ust.',
        15: 'Kajti ti boš njegova priča vsem ljudem o tem, kar si videl in slišal.',
        16: 'In sedaj, zakaj se mudiš? Vstani in bodi krščen in izperi svoje grehe ter kliči Gospodovo ime.‹',
        17: 'In pripetilo se je, ko sem ponovno prišel v Jeruzalem, medtem ko sem molil v templju, da sem bil v zamaknjenju;',
        18: 'in videl sem njega, ki mi je rekel: ›Podvizaj se in pojdi hitro iz Jeruzalema, kajti ne bodo sprejeli tvojega pričevanja glede mene.‹',
        19: 'In rekel sem: ›Gospod, oni vedo, da sem v vsaki sinagogi zapiral in pretepal te, ki so verovali vate,',
        20: 'in ko je bila prelita kri tvojega mučenca Štefana, sem tudi sam stal poleg in soglašal k njegovi smrti in varoval obleko teh, ki so ga usmrtili.‹',
        21: 'In rekel mi je: ›Pojdi, kajti od tod te bom poslal daleč k poganom.‹ «',
        22: 'In poslušali so ga do te besede in nato so povzdignili svoje glasove ter rekli: »Proč z zemlje z njim, kajti ne spodobi se, da bi živel.«',
        23: 'In ko so zakričali in odvrgli svoja oblačila ter v zrak metali prah,',
        24: 'mu je vrhovni poveljnik velel, naj bo priveden v grad in zaukazal, da naj bi bil zaslišan z bičanjem, da bi lahko izvedel, zakaj so tako vpili zoper njega.',
        25: 'In ko so ga zvezali z jermeni, je Pavel rekel stotniku, ki je stal poleg: »Ali je za vas zakonito, da bičate človeka, ki je Rimljan in neobsojen?«',
        26: 'Ko je stotnik to slišal, je odšel in povedal vrhovnemu poveljniku, rekoč: »Pazi, kaj delaš, kajti ta človek je Rimljan.«',
        27: 'Potem je prišel vrhovni poveljnik in mu rekel: »Povej mi, ali si Rimljan?« Rekel je: »Da.«',
        28: '§ In vrhovni poveljnik je odgovoril: »Z velikim zneskom sem dosegel to svobodo.« Pavel pa je rekel: »Toda jaz sem bil rojen svoboden.«',
        29: 'Potem so nemudoma odstopili od njega ti, ki naj bi ga zaslišali. In tudi vrhovni poveljnik je bil prestrašen, potem ko je izvedel, da je bil Rimljan in ker ga je zvezal.',
        30: 'Naslednji dan, ker je hotel zagotovo izvedeti, zakaj je bil obtožen od Judov, ga je odvezal od njegovih jermenov ter visokim duhovnikom in vsemu njihovemu vélikemu zboru ukazal, da se prikažejo in Pavla privedel dol ter ga postavil prednje.',
    },
    23: {
        1: 'In ko je Pavel iskreno gledal véliki zbor, je rekel: »Možje in bratje, do danes sem živel po vsej dobri vesti pred Bogom.«',
        2: 'Véliki duhovnik Hananija pa je ukazal tem, ki so stali poleg, da ga udarijo po ustih.',
        3: 'Potem mu je Pavel rekel: »Bog bo udaril tebe, ti pobeljeni zid, kajti sediš, da mi sodiš po postavi, velevaš pa, da sem udarjen v nasprotju s postavo?«',
        4: 'In ti, ki so stali poleg, so rekli: »Ti zasramuješ Božjega vélikega duhovnika?«',
        5: 'Potem je Pavel rekel: »Nisem vedel, bratje, da je véliki duhovnik, kajti pisano je: ›O vladarju svojih ljudi ne boš govoril hudobno.‹«',
        6: '§ Toda ko je Pavel zaznal, da jih je bilo v vélikem zboru en del saducejev, drugi pa farizeji, je v zboru vzkliknil: »Možje in bratje, jaz sem farizej, sin farizeja; zaradi upanja in vstajenja mrtvih sem poklican na zaslišanje.«',
        7: 'In ko je tako rekel, je med farizeji in saduceji nastalo nesoglasje, in množica je bila razdeljena.',
        8: 'Kajti saduceji pravijo, da ni vstajenja niti angela niti duha, toda farizeji oboje priznavajo.',
        9: '§ In nastalo je veliko vpitje. In pisarji, ki so bili iz farizejskega dela, so vstali ter se prepirali, rekoč: »Na tem človeku ne najdemo nobenega zla, temveč če mu je govoril duh ali angel, se ne bojujmo proti Bogu.«',
        10: 'In ko je nastalo veliko nesoglasje, je vrhovni poveljnik, ker se je bal, da ne bi Pavla raztrgali na koščke, ukazal vojakom, da gredo dol in ga na silo vzamejo izmed njih ter ga privedejo v grad.',
        11: 'In naslednjo noč je poleg njega stal Gospod ter rekel: »Bodi dobre volje, Pavel, kajti kakor si pričeval o meni v Jeruzalemu, tako moraš pričevati tudi v Rimu.«',
        12: 'In ko je bil dan, so se nekateri izmed Judov zbrali skupaj ter se pod prekletstvom zavezali, rekoč, da ne bodo niti jedli niti pili, dokler Pavla ne ubijejo.',
        13: 'In bilo jih je več kot štirideset, ki so sklenili to zaroto.',
        14: 'In prišli so k visokim duhovnikom in starešinam ter rekli: »Mi smo se pod velikim prekletstvom zavezali, da ne bomo ničesar jedli, dokler Pavla ne umorimo.«',
        15: 'Zdaj torej z vélikim zborom naznanite vrhovnemu poveljniku, da ga naslednji dan privede dol k vam, kot da glede njega zahtevate nekaj bolj podrobnega, mi pa smo pripravljeni, da ga ubijemo, preden pride blizu.',
        16: 'In ko je sin Pavlove sestre slišal o njihovem prežanju, je odšel in vstopil v grad ter povedal Pavlu.',
        17: 'Potem je Pavel k sebi poklical enega izmed stotnikov in rekel: »Spremite tega mladeniča k vrhovnemu poveljniku, kajti povedati mu ima neko stvar.«',
        18: 'Tedaj ga je ta vzel in ga spremil k vrhovnemu poveljniku in rekel: »Jetnik Pavel me je poklical k sebi in me prosil, da tega mladeniča spremim k tebi, ki ti ima nekaj povedati.«',
        19: 'Potem ga je vrhovni poveljnik prijel za roko in odšel z njim stran na samo ter ga vprašal: »Kaj je to, kar mi imaš povedati?«',
        20: 'In rekel je: »Judje so se strinjali, da od tebe zahtevajo, da jim naslednji dan privedeš Pavla dol v véliki zbor, kakor da bodo od njega zahtevali nekaj bolj podrobnega.',
        21: 'Ampak ne ukloni se jim, kajti nanj preži izmed njih več kot štirideset mož, ki so se s prisego zavezali, da ne bodo niti jedli niti pili, dokler ga ne ubijejo. In sedaj so pripravljeni, ker od tebe pričakujejo obljubo.«',
        22: 'Tako je potem vrhovni poveljnik pustil mladeniču oditi in mu naročil: » Glej, da nobenemu človeku ne poveš, da si mi razodel te besede.«',
        23: 'In k sebi je poklical dva stotnika, rekoč: »Pripravita dvesto vojakov in sedemdeset konjenikov in dvesto suličarjev, da gredo ob tretji nočni uri v Cezarejo,',
        24: 'in priskrbite jim živali, da bodo lahko Pavla posadili nanje in ga varno privedite k voditelju Feliksu.«',
        25: 'In napisal je pismo na ta način:',
        26: '›Klavdij Lizija pošilja pozdrav nadvse odličnemu voditelju Feliksu.',
        27: 'Tega moža so Judje prijeli in bi ga bili ubili. Potem sem prišel z vojsko in ko sem izvedel, da je bil Rimljan, sem ga rešil.',
        28: 'In ko sem hotel izvedel razlog, zakaj so ga obtožili, sem ga privedel v njihov véliki zbor.',
        29: 'O njem sem zaznal, da je obtožen vprašanj iz svoje postave, toda k njegovi obtožbi ni položenega ničesar vrednega smrti ali ujetništva.',
        30: 'In ko mi je bilo povedano, kako Judje prežijo na tega človeka, sem ga nemudoma poslal k tebi in tudi njegovim tožnikom sem dal zapoved, da pred teboj povedo, kar so imeli zoper njega. Zbogom.‹',
        31: 'Potem so vojaki, kakor jim je bilo ukazano, vzeli Pavla in ga ponoči privedli do Antipatríde.',
        32: 'Naslednji dan so konjenike pustili, da gredo z njim in se vrnili h gradu.',
        33: 'Ki so, ko so prišli v Cezarejo in poslanico izročili voditelju, predenj izročili tudi Pavla.',
        34: 'In ko je voditelj pismo prebral, je vprašal, iz katere province je. In ko je razumel, da je bil iz Kilikije,',
        35: 'je rekel: »Poslušal te bom, ko pridejo tudi tvoji tožniki.« In ukazal ga je zadržati v Herodovi sodni dvorani.',
    },
    24: {
        1: 'Po petih dneh pa je prišel dol Hananija, véliki duhovnik, s starešinami in z nekim govornikom po imenu Tertúl, ki je voditelja poučil zoper Pavla.',
        2: 'In ko je bil le-ta poklican, ga je Tertúl začel obtoževati, rekoč: »Glede na to, da po tebi uživamo veliko spokojnost in da so po tvoji previdnosti temu narodu storjena zelo plemenita dejanja,',
        3: '§ to priznavamo vedno in na vseh krajih, najplemenitejši Feliks, z vso hvaležnostjo.',
        4: 'Vendar da te ne bom še bolj zadrževal, te prosim, da nam po svoji dobrotljivosti prisluhneš nekaj besed.',
        5: 'Kajti tega človeka smo spoznali [za] kužnega in povzročitelja upora med vsemi Judi po vsem svetu in kolovodja ločine Nazarečanov,',
        6: '§ ki je poskušal oskruniti tudi tempelj; ki smo prijeli in hoteli soditi glede na našo postavo.',
        7: '§ Vendar je nad nas prišel vrhovni poveljnik Lizija in ga z veliko silo odvedel iz naših rok',
        8: '§ in njegovim tožnikom velel, da pridejo k tebi; s čigar zasliševanjem si boš lahko pridobil spoznanje o vseh teh stvareh, česar ga obtožujemo.«',
        9: 'In tudi Judje so soglašali, rekoč, da so bile te stvari takšne.',
        10: 'Nató je Pavel, potem ko mu je voditelj dal znamenje, da govori, odgovoril: »Ker vem, da si bil že mnogo let sodnik temu narodu, se še bolj vedro zagovarjam,',
        11: 'zato, da boš lahko razumel, da je šele dvanajst dni, odkar sem odšel gor v Jeruzalem, da bi oboževal.',
        12: 'In niti me niso našli v templju razpravljati s katerimkoli človekom niti podpihovati množice, ne v sinagogah ne v mestu.',
        13: 'Niti ne morejo dokazati besed, s katerimi me sedaj obtožujejo.',
        14: 'Toda to ti priznam, da po poti, ki ji pravijo kriva vera, na ta način obožujem Boga svojih očetov in verujem vse stvari, ki so zapisane v postavi in prerokih,',
        15: 'in upanje imam v Boga, ki ga tudi sami dopuščajo, da bo vstajenje mrtvih, tako pravičnih kakor nepravičnih.',
        16: 'In v tem sebe vežbam, da imam vest nenehno povsem brez prestopka pred Bogom in pred ljudmi.',
        17: 'Torej po mnogih letih sem prišel, da svojemu narodu prinesem miloščine in daritve.',
        18: 'Nakar so me neki Judje iz Azije našli v templju očiščenega, niti skupaj z množico niti s hrupom.',
        19: 'Ki bi morali biti tukaj pred teboj in ugovarjati, če bi imeli karkoli zoper mene.',
        20: 'Sicer naj ti isti tukaj povedo, če so našli na meni kakršnokoli zlo dejanje, medtem ko sem stal pred vélikim zborom,',
        21: 'razen, če je to zaradi tistega enega glasu, ko sem med njimi stal in vzkliknil: ›Gledé vstajenja mrtvih ste me danes poklicali na zaslišanje.‹«',
        22: 'In ko je Feliks, ki je imel popolnejše spoznanje o tej poti, slišal te besede, jih je preložil ter rekel: »Ko bo prišel dol vrhovni poveljnik Lizija, bom spoznal vse o vaši zadevi.«',
        23: '§ In stotniku je ukazal, da varuje Pavla in mu pusti imeti prostost in da naj nikomur od njegovih znancev ne bi prepovedal streči ali priti k njemu.',
        24: '§ In po nekaj dneh, ko je prišel Feliks s svojo ženo Druzílo, ki je bila Judinja, je poklical Pavla in ga poslušal glede vere v Kristusa.',
        25: 'In ko je razpravljal o pravičnosti, zmernosti in sodbi, ki pride, je Feliks zatrepetal in odgovoril: »Za sedaj pojdi svojo pot. Ko bom imel primeren čas, te bom poklical.«',
        26: '§ Upal je tudi, da bi mu bil od Pavla dan denar, da bi ga lahko osvobodil, zaradi česar ga je pogosteje poklical in se posvetoval z njim.',
        27: 'Toda po dveh letih pa je na Feliksovo mesto prišel Porkij Fest. Feliks pa, voljan ustreči Judom, je Pavla pustil zvezanega.',
    },
    25: {
        1: 'Torej ko je Fest prišel v provinco, se je po treh dneh povzpel iz Cezareje v Jeruzalem.',
        2: 'Potem sta ga véliki duhovnik in judovski voditelj poučila zoper Pavla in ga rotila',
        3: 'ter zoper njega želela naklonjenosti, da bi ga dal poslati v Jeruzalem, prežeč na poti, da ga ubijejo.',
        4: 'Toda Fest je odgovoril, da naj bo Pavel čuvan v Cezareji in da bo sam v kratkem odšel tja.',
        5: '»Naj torej tisti,« je rekel, »ki so med vami zmožni, odidejo z menoj dol in tega moža obtožijo, če je v njem kakršnakoli zlobnost.«',
        6: 'In ko se je med njimi mudil več kot deset dni, je odšel dol v Cezarejo; in naslednji dan je sedeč na sodnem stolu zapovedal, naj pripeljejo Pavla.',
        7: 'In ko je ta prišel, so naokoli stali Judje, ki so prišli dol iz Jeruzalema in zoper Pavla vložili mnoge in boleče ovadbe, ki jih niso mogli dokazati.',
        8: 'Medtem se je zagovarjal: »Niti zoper judovsko postavo, niti zoper tempelj, niti zoper cesarja nisem čisto nič zagrešil.«',
        9: 'Toda Fest je, voljan ustreči Judom, Pavlu odgovoril in rekel: »Hočeš iti gor v Jeruzalem in biti tam, pred menoj, sojen o teh stvareh?«',
        10: 'Potem je Pavel rekel: »Pred cesarskim sodnim stolom stojim, kjer moram biti sojen. Judom nisem storil nobene krivice, kakor ti zelo dobro veš.',
        11: 'Kajti če sem prestopnik ali sem zagrešil karkoli vrednega smrti, se ne branim umreti, toda če ni nobene od teh stvari, za katere me ti tožijo, me noben človek ne more izročiti njim. Na cesarja se sklicujem.«',
        12: 'Tedaj je Fest, ko se je posvetoval z zborom, odgovoril: »Na cesarja si se skliceval? K cesarju pojdeš.«',
        13: 'In po nekaj dneh sta v Cezarejo prišla kralj Agripa in Bereníka, da pozdravita Festa.',
        14: 'In ko sta bila tam mnogo dni, je Fest kralju razodel Pavlovo zadevo, rekoč: »Tukaj je nek mož, ki ga je Feliks pustil v vezeh,',
        15: 'o katerem so me, ko sem bil v Jeruzalemu, visoki duhovniki in judovski starešine obvestili, ker so proti njemu želeli imeti sodbo.',
        16: 'Katerim sem odgovoril: ›Rimljani nimajo navade kateregakoli človeka izročiti, da umre, preden se ta, ki je obtožen, ne sooči s tožniki in ima dovoljenje, da se brani glede zločina, vloženega zoper njega.‹',
        17: 'Torej ko so prišli sèm, sem brez kakršnegakoli odlašanja naslednji dan sédel na sodni stol in ukazal, da moža privedejo.',
        18: 'Proti kateremu, ko so tožniki vstali, niso prinesli nobene obtožbe o takšnih stvareh, kakor sem predpostavljal,',
        19: 'temveč so imeli zoper njega neka vprašanja o njihovem lastnem praznoverju in o nekem Jezusu, ki je bil mrtev, o katerem je Pavel trdil, da živi.',
        20: 'In ker sem dvomil o takšnem načinu zaslišanj, sem ga vprašal, ali bi odšel v Jeruzalem in bi bil tam sojen o teh stvareh.',
        21: '§ Toda ko se je Pavel skliceval, da se zadrži za Avgustovo zaslišanje, sem ukazal, da ga stražijo, dokler ga ne pošljem k cesarju.«',
        22: 'Potem je Agripa rekel Festu: »Tudi sam bi rad slišal tega človeka.« »Naslednji dan,« je rekel, »ga boš slišal.«',
        23: 'In naslednji dan, ko sta z velikim pompom prišla Agripa in Bereníka in vstopila na kraj zaslišanja z vrhovnimi poveljniki ter glavnimi možmi mesta, je bil na Festovo zapoved priveden Pavel.',
        24: 'In Fest je rekel: »Kralj Agripa in vsi ljudje, ki ste z nami tukaj prisotni, vidite tega človeka, glede katerega se je vsa množica Judov pogajala z menoj, tako v Jeruzalemu kakor tudi tukaj in kričala, da ne bi smel več živeti.',
        25: 'Toda ko sem spoznal, da ni zagrešil ničesar vrednega smrti in da se je on sam skliceval na Avgusta, sem določil, da ga pošljem.',
        26: 'O katerem ne vem nobene zanesljive stvari, da napišem svojemu gospodu. In zato sem ga privedel pred vas in zlasti predte, oh kralj Agripa, da bi po zaslišanju lahko imel kaj napisati.',
        27: 'Kajti zdi se mi nerazumno poslati jetnika in istočasno ne naznaniti zločinov, vloženih zoper njega.«',
    },
    26: {
        1: 'Potem je Agripa rekel Pavlu: »Dovoljeno ti je, da se zagovarjaš.« Nató je Pavel iztegnil svojo roko in se zagovarjal:',
        2: '»Imam se za srečnega, kralj Agripa, ker se bom danes pred teboj zagovarjal gledé vseh stvari, katere me Judje obtožujejo,',
        3: 'še posebej, ker te poznam, da si poznavalec vseh običajev in vprašanj, ki so med Judi, te zaradi tega rotim, da me potrpežljivo poslušaš.',
        4: 'Moj življenjski slog od moje mladosti, ki je bila najprej med mojim lastnim narodom v Jeruzalemu, poznajo vsi Judje,',
        5: 'ki so me poznali od začetka, če bi [le] želeli pričevati, da sem po najstrožji ločini našega bogoslužja živel kot farizej.',
        6: 'In sedaj stojim in sem sojen zaradi upanja o od Boga dani obljubi našim očetom.',
        7: 'K tej obljubi se naši dvanajsteri rodovi, ki dan in noč iskreno služijo Bogu, nadejajo, da se uresniči. Zaradi tega upanja, kralj Agripa, sem obtožen od Judov.',
        8: 'Zakaj bi vam bila neverjetna misel, da bi Bog obujal mrtve?',
        9: 'Jaz sem sam pri sebi resnično mislil, da moram mnoge stvari narediti nasprotno imenu Jezusa Nazarečana.',
        10: 'Kar sem tudi počel v Jeruzalemu. In mnoge izmed svetih sem zapiral v ječo, ker sem prejel oblast od visokih duhovnikov. In ko so jih morili, sem dajal svoj glas zoper nje.',
        11: 'In pogosto sem jih v vsaki sinagogi kaznoval ter jih silil k bogokletju in zoper njih sem bil silno besen. Preganjal sem jih celó v tujih mestih.',
        12: 'Nakar, ko sem odšel v Damask, z oblastjo in pooblastilom od visokih duhovnikov,',
        13: 'sem sredi dneva, oh kralj, na poti videl svetlobo z neba, nad sijajem sonca, ki je svetilo naokoli mene in teh, ki so potovali z menoj.',
        14: 'In ko smo vsi popadali na zemljo, sem zaslišal glas, ki mi je spregovoril in v hebrejskem jeziku rekel: ›Savel, Savel, zakaj me preganjaš? Zate je to težko, da se upiraš bodicam.‹',
        15: 'In rekel sem: ›Kdo si ti, Gospod?‹ In rekel je: ›Jaz sem Jezus, ki ga ti preganjaš.',
        16: 'Toda vstani in stopi na svoja stopala, kajti prikazal sem se ti zaradi tega namena, da te naredim za služabnika in pričo tako o teh stvareh, ki si jih videl, kakor o teh stvareh, v katerih se ti bom prikazal,',
        17: 'in te reševal pred ljudmi ter pred pogani, h katerim te sedaj pošiljam,',
        18: 'da odpreš njihove oči in da jih obrneš od teme k svetlobi in od Satanove oblasti k Bogu, da bi lahko prejeli odpuščanje grehov in dediščino med temi, ki so posvečeni po veri, ki je v meni.‹',
        19: 'Nakar, oh kralj Agripa, nisem bil neposlušen nebeškemu videnju,',
        20: 'temveč sem se najprej pokazal tem iz Damaska in v Jeruzalemu in po vseh celotnih krajih Judeje in potem poganom, da bi se pokesali in se obrnili k Bogu in opravljali dela, primerna kesanju.',
        21: 'Zaradi teh razlogov so me v templju Judje zgrabili in me poskušali ubiti.',
        22: 'Ker sem torej dobil pomoč od Boga, sem nadaljeval do današnjega dne in pričeval tako malim kakor velikim in nisem govoril nobenih drugih besed kakor te, ki so jih govorili preroki in Mojzes, da naj bi se zgodile,',
        23: 'da naj bi Kristus trpel in da naj bi bil on prvi, ki bi vstal od mrtvih in bi naznanil svetlobo ljudem ter poganom.«',
        24: 'In ko se je tako zagovarjal, je Fest z močnim glasom rekel: »Pavel, izgubil si pamet. Mnogo učenja te je naredilo norega.«',
        25: 'Vendar je ta odvrnil: »Nisem zmešan, najplemenitejši Fest, temveč govorim besede resnice in treznosti.',
        26: 'Kajti kralj, pred katerim tudi sam pogumno govorim, ve o teh stvareh, kajti prepričan sem, da nobena teh stvari pred njim ni skrita, kajti ta stvar se ni zgodila v zakotju.',
        27: 'Kralj Agripa, verjameš prerokom? Vem, da verjameš.«',
        28: 'Potem je Agripa rekel Pavlu: »Skoraj me pregovoriš, da postanem kristjan.«',
        29: 'In Pavel je rekel: »Bog daj, da ne bi bil samo ti, temveč tudi vsi, ki so me danes slišali, tako skoraj, kakor povsem tako kakor jaz, toda brez teh vezi.«',
        30: 'In ko je tako govoril, so vstali kralj in voditelj in Bereníka in vsi, ki so sedeli z njimi.',
        31: 'In ko so odšli proč, so se med seboj pogovarjali, rekoč: »Ta človek ne dela nič vrednega smrti ali ujetništva.«',
        32: 'Potem je Agripa rekel Festu: »Tega človeka bi lahko izpustili na prostost, če se ne bi skliceval na cesarja.«',
    },
    27: {
        1: 'In ko je bilo določeno, da naj bi odpluli v Italijo, so Pavla in nekatere druge jetnike izročili nekomu, po imenu Julij, stotniku Avgustove čete.',
        2: 'In ko smo vstopili na ladjo iz Adramítija, smo odrinili ter mislili pluti ob obalah Azije. Z nami je bil neki Aristarh, Makedonec iz Tesaloníke.',
        3: '§ In naslednjega dne smo pristali v Sidónu. In Julij je s Pavlom človekoljubno ravnal ter mu dal dovoljenje za odhod na kopno k svojim prijateljem, da se okrepi.',
        4: 'In ko smo od tam odpluli, smo jadrali pod Ciprom, ker so bili vetrovi nasprotni.',
        5: 'In ko smo jadrali prek morja Kilikije in Pamfilije, smo prišli v Miro, mesto v Likiji.',
        6: 'In tam je stotnik našel ladjo iz Aleksandrije, ki je plula v Italijo, in nas vkrcal nanjo.',
        7: 'In ko smo mnogo dni počasi jadrali in smo komaj prišli nasproti Knidosa in ker nam veter ni dovoljeval, smo jadrali pod Kreto, nasproti Salmone,',
        8: 'in ko smo jo komaj prešli, smo prišli v kraj, ki se imenuje Dobri pristani; blizu katerega je bilo mesto Lasája.',
        9: 'Torej potem ko je bilo porabljenega mnogo časa in ko je bilo torej jadranje nevarno, ker je post sedaj že minil, jih je Pavel opomnil',
        10: 'in jim rekel: »Možje, zaznavam, da bo to potovanje z bolečino in veliko škodo, ne samo za tovor in ladjo, temveč tudi za naša življenja.«',
        11: 'Vendar je stotnik bolj zaupal gospodarju in lastniku ladje kakor tem besedam, ki so bile spregovorjene po Pavlu.',
        12: 'In ker pristanišče ni bilo primerno za prezimovanje, je večina svetovala, da tudi od tam odplujejo, če bi na kakršenkoli način lahko dosegli Fojniks in tam prezimili; ki je pristanišče na Kreti in leži proti jugozahodu in severozahodu.',
        13: 'In ko je nežno pihal južni veter, ker so mislili, da so dosegli svoj namen, so od tam dvignili sidro ter jadrali blizu Krete.',
        14: 'Toda ne dolgo potem se proti njej dvigne viharen veter, imenovan evrakílon.',
        15: 'In ko je bila ladja ujeta in ni mogla jadrati proti vetru, smo jo pustili peljati.',
        16: 'In ko je drvela pod nekim otokom, ki je bil imenovan Kavda, smo imeli mnogo dela, da zavarujemo čoln.',
        17: 'Ko so ga dvignili, so uporabili pripomočke ter opasali ladjo in ker so se bali, da ne bi nepričakovano nasedli na sipine, so spustili jadra in tako smo bili gnani.',
        18: 'In ker nas je vihar silno premetaval, so naslednji dan razbremenili ladjo,',
        19: 'in tretji dan smo z svojimi lastnimi rokami odvrgli ladijsko opremo.',
        20: 'In ko se mnogo dni ni pokazalo niti sonce niti zvezde in je na nas pritiskal ne majhen vihar, je bilo odvzeto vsako upanje, da bi bili rešeni.',
        21: 'Toda po dolgi vzdržnosti je Pavel stopil v sredo mednje in rekel: »Možje, morali bi mi prisluhniti in ne odpluti od Krete ter tako ne pridobiti te škode in izgube.',
        22: 'In sedaj vas spodbujam, da bodite dobre volje, kajti med vami ne bo nobene izgube kateregakoli človeškega življenja, razen ladje.',
        23: 'Kajti to noč je poleg mene stal angel Boga, čigar sem in ki mu služim,',
        24: 'rekoč: ›Ne boj se, Pavel. Priveden moraš biti pred cesarja in glej, Bog ti je podaril vse te, ki jadrajo s teboj.‹',
        25: 'In zato, možje, bodite dobre volje, kajti verjamem Bogu, da bo tako, kakor mi je bilo rečeno.',
        26: 'Vendar moramo biti vrženi na nek otok.«',
        27: 'Toda ko je prišla štirinajsta noč, ko smo bili gnani gor in dol po Adriji, se je okoli polnoči mornarjem zdelo, da so se približali neki deželi.',
        28: 'In izmerili so globino in jo namerili dvajset sežnjev, in ko so se pomaknili malo naprej, so ponovno izmerili in jo namerili petnajst sežnjev.',
        29: 'Potem so, ker so se bali, da ne bi padli na skale, s krme vrgli štiri sidra in hrepeneli po dnevu.',
        30: 'In medtem ko so mornarji nameravali pobegniti z ladje, ko so hoteli čoln spustiti v morje, pod krinko, kot da bodo vrgli sidra tudi iz premca,',
        31: 'je Pavel rekel stotniku in vojakom: »Razen če ti ne ostanejo na ladji, vi ne morete biti rešeni.«',
        32: 'Potem so vojaki presekali vrvi čolna in ga pustili pasti.',
        33: 'In medtem ko je prihajal dan, jih je Pavel vse rotil, naj vzamejo hrano, rekoč: »Danes je štirinajsti dan, ko ste čakali in vztrajali ter se postili, ne da bi kaj vzeli.',
        34: 'Zato vas prosim, da vzamete nekaj hrane, kajti to je za vaše zdravje, kajti nikomur od vas niti las ne bo padel z glave.«',
        35: 'In ko je tako govoril, je vzel kruh in se v prisotnosti vseh zahvalil Bogu; in ko ga je prelomil, je začel jesti.',
        36: 'Potem so bili vsi dobre volje in so tudi sami vzeli nekaj hrane.',
        37: 'Vseh skupaj pa nas je bilo na ladji dvesto šestinsedemdeset duš.',
        38: 'In ko so se dovolj najedli, so razbremenili ladjo in v morje vrgli pšenico.',
        39: 'In ko je bil dan, niso poznali kopnine, toda odkrili so nek zaliv z obalo, v katerega bi radi, če bi bilo mogoče, vrinili ladjo.',
        40: 'In ko so dvignili sidra, so se predali morju ter odvezali krmilne vrvi in dvignili veliko jadro k vetru ter se usmerili proti obali.',
        41: 'In ko je nepričakovano prišla na kraj, kjer sta se stikali dve morji, je ladja nasedla, in sprednji del je trdno obtičal in ostal nepremičen, toda zadnji del je bil zaradi sile valov razbit.',
        42: 'In nasvet vojakov je bil, da pobijejo jetnike, da ne bi kateri od njih odplaval in pobegnil.',
        43: 'Toda stotnik, voljan rešiti Pavla, je preprečil njihov namen in ukazal, naj se tisti, ki lahko plavajo, najprej vržejo v morje in dosežejo kopno,',
        44: 'ostali pa, nekateri na deskah in nekateri na ladijskih razbitinah. In tako se je zgodilo, da so se vsi varno rešili na kopno.',
    },
    28: {
        1: 'In ko so bili rešeni, so potem izvedeli, da se otok imenuje Malta.',
        2: '§ In barbarsko ljudstvo nam je pokazalo ne malo prijaznosti, kajti prižgali so ogenj in nas zaradi navzočega dežja in zaradi mraza, vse sprejeli.',
        3: 'In ko je Pavel nabral sveženj vej in jih položil na ogenj, je zaradi vročine ven prišel gad in se oprijel njegove roke.',
        4: 'In ko so barbari videli strupeno žival viseti na njegovi roki, so med seboj govorili: »Brez dvoma je ta človek morilec, čeprav je ušel morju, ki mu maščevanje vendar ne pusti živeti.«',
        5: 'On pa je žival otresel v ogenj in ni čutil nobene škode.',
        6: 'Vendar so gledali, ko naj bi imel oteklino ali nenadoma padel mrtev. Toda potem, ko so dolgo časa gledali in so videli, da se mu ni zgodilo nič hudega, so spremenili svoja mišljenja in rekli, da je bil bog.',
        7: 'V istih četrtih so bile posesti vodilnega moža otoka, katerega ime je bilo Publij, ki nas je sprejel in nas tri dni prijazno prenočeval.',
        8: 'Pripetilo pa se je, da je Publijev oče ležal bolan zaradi vročice in zaradi krvave griže; h kateremu je vstopil Pavel in molil ter položil svoji roki nanj in ga ozdravil.',
        9: 'Torej ko se je to zgodilo, so prišli tudi drugi, ki so na otoku imeli bolezni in so bili ozdravljeni,',
        10: 'ki so nas prav tako počastili z mnogimi častmi. In ko smo odšli, so nas obložili s takšnimi stvarmi, kot je bilo potrebno.',
        11: '§ In po treh mesecih smo se vkrcali na ladjo iz Aleksandrije, ki je prezimila na otoku, katere znamenje sta bila Kastor in Poluks.',
        12: 'In ko smo se izkrcali v Sirakuzi, smo se tam mudili tri dni.',
        13: 'In od tam smo šli po ovinkih ter prišli v Région. In po enem dnevu je zapihal južni veter in naslednji dan smo prišli v Putéole,',
        14: 'kjer smo našli brate in želeli so, da ostanemo z njimi sedem dni; in tako smo odšli proti Rimu.',
        15: 'In ko so bratje slišali o nas, so prišli od tam, da nas srečajo, prav do Apijevega trga in Treh Tavern. Ko jih je Pavel zagledal, se je zahvalil Bogu in se opogumil.',
        16: '§ In ko smo prišli v Rim, je stotnik jetnike izročil poveljniku straže, toda Pavlu je bilo dovoljeno, da prebiva sam zase z vojakom, ki ga je varoval.',
        17: 'In pripetilo se je, da je po treh dneh Pavel sklical skupaj judovske voditelje in ko so prišli skupaj, jim je rekel: »Možje in bratje, čeprav nisem ničesar zagrešil proti ljudem ali običajem naših očetov, sem bil vendarle jetnik, iz Jeruzalema izročen v roke Rimljanom.',
        18: 'Ki so me po zaslišanju hoteli izpustiti, ker na meni ni bilo razloga za smrt.',
        19: 'Toda ko so Judje temu ugovarjali, sem se bil primoran sklicevati na cesarja, ne da bi moral obtoževati svoj narod.',
        20: 'Zaradi tega razloga sem vas torej dal poklicati, da vas vidim in spregovorim z vami, zato ker sem s to verigo zvezan zaradi Izraelovega upanja.«',
        21: 'In rekli so mu: »Glede tebe nismo prejeli niti pisem iz Judeje niti nobeden izmed bratov, ki je prišel, [te] ni naznanil ali škodljivo govoril o tebi.',
        22: 'Toda od tebe želimo slišati, kaj misliš; kajti glede te ločine vemo, da ji povsod ugovarjajo.«',
        23: 'In ko so mu določili dan, so mnogi prišli k njemu v njegovo stanovanje; katerim je od jutra do večera pojasnjeval in dokazoval Božje kraljestvo, jih prepričeval glede Jezusa, tako iz Mojzesove postave kakor iz prerokov.',
        24: 'In nekateri so verjeli besedam, ki so bile govorjene, nekateri pa niso verjeli.',
        25: 'In ko se med seboj niso strinjali, so odšli, po tem, ko je Pavel spregovoril eno besedo: »Dobro je Sveti Duh govoril našim očetom po preroku Izaiju,',
        26: 'rekoč: ›Pojdi k tem ljudem in reci: ›S poslušanjem boste slišali, pa ne boste razumeli; in z gledanjem boste videli, pa ne zaznali;',
        27: 'kajti srce teh ljudi je otopelo in njihova ušesa so naglušna in svoje oči so zaprli, da ne bi videli s svojimi očmi in [da ne bi] slišali s svojimi ušesi in [da ne bi] razumeli s svojim srcem in [da ne bi] bili spreobrnjeni in [bi] jih jaz ozdravil.‹‹',
        28: 'Bodi vam torej znano, da je Božja rešitev duš poslana k poganom in da jo bodo poslušali.«',
        29: '§ In ko je rekel te besede, so Judje odšli in med seboj imeli veliko razpravljanja.',
        30: 'In Pavel je celi dve leti prebival v lastni najeti hiši in sprejemal vse, ki so prihajali k njemu',
        31: 'ter z vso samozavestjo oznanjal Božje kraljestvo in učil te stvari, ki se tičejo Gospoda Jezusa Kristusa in noben človek mu ni branil.',
    },
}
